/* ============================================================
   VOLT RALLY — UI
   ============================================================ */
@font-face {
  font-family: 'Orbitron';
  src: url('./vendor/fonts/orbitron.woff2') format('woff2');
  font-weight: 400 900;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./vendor/fonts/rajdhani-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./vendor/fonts/rajdhani-500.woff2') format('woff2');
  font-weight: 500;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./vendor/fonts/rajdhani-600.woff2') format('woff2');
  font-weight: 600;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./vendor/fonts/rajdhani-700.woff2') format('woff2');
  font-weight: 700;
  font-display: swap;
}

:root {
  --bg: #05030c;
  --ink: #ecf8ff;
  --muted: #8fa5b8;
  --cyan: #2ce8ff;
  --cyan-hot: #9ffcff;
  --magenta: #ff35c8;
  --magenta-hot: #ff9fe4;
  --lime: #c8ff4a;
  --orange: #ff8a2b;
  --panel: rgba(8, 13, 27, 0.66);
  --line: rgba(120, 225, 255, 0.24);
  --display: 'Orbitron', 'Arial Black', sans-serif;
  --body: 'Rajdhani', 'Trebuchet MS', sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

body {
  touch-action: none;
  overscroll-behavior: none;
}

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 110%, rgba(0, 190, 255, 0.16), transparent 55%),
    #05030c;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

/* ---------- ambient screen treatment ---------- */
#fxScan {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0.22;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.24) 3px,
    transparent 4px
  );
  mix-blend-mode: multiply;
}
#fxTint {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.25s ease;
  background:
    radial-gradient(ellipse at 50% 50%, transparent 22%, rgba(25, 100, 255, 0.28) 100%),
    linear-gradient(180deg, rgba(50, 210, 255, 0.1), rgba(98, 60, 255, 0.05));
  backdrop-filter: saturate(0.55) hue-rotate(-10deg);
  -webkit-backdrop-filter: saturate(0.55) hue-rotate(-10deg);
}
#fxTint.on { opacity: 1; }

#fxFlash {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  background: radial-gradient(circle at 50% 44%, rgba(255, 255, 255, 0.8), rgba(255, 130, 40, 0.22) 45%, transparent 72%);
  opacity: 0;
}
#fxFlash.fire { animation: flashOut 0.5s ease-out forwards; }
#fxFlash.warp { animation: warpOut 0.55s ease-out forwards; }
@keyframes flashOut {
  0% { opacity: 0.95; transform: scale(1.08); }
  100% { opacity: 0; transform: scale(1); }
}
@keyframes warpOut {
  0% { opacity: 0.55; background: radial-gradient(circle, rgba(160, 250, 255, 0.9), rgba(40, 110, 255, 0.2) 50%, transparent 70%); }
  100% { opacity: 0; }
}

/* ============================================================
   HUD
   ============================================================ */
.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  padding:
    calc(16px + env(safe-area-inset-top))
    calc(22px + env(safe-area-inset-right))
    calc(18px + env(safe-area-inset-bottom))
    calc(22px + env(safe-area-inset-left));
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.45s ease, visibility 0.45s;
}
.hud.live { opacity: 1; visibility: visible; }

.topbar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 18px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 4px;
  text-shadow: 0 0 18px rgba(44, 232, 255, 0.4);
}
.brand-mark {
  width: 9px;
  height: 28px;
  background: linear-gradient(180deg, var(--cyan), rgba(44, 232, 255, 0.1));
  box-shadow: 0 0 14px var(--cyan);
  clip-path: polygon(0 0, 100% 18%, 100% 100%, 0 82%);
}
.brand-text {
  font-family: var(--display);
  font-weight: 900;
  font-size: 15px;
  letter-spacing: 0.24em;
  line-height: 1;
  display: flex;
  gap: 6px;
  color: #eaffff;
}
.brand-text em {
  font-style: normal;
  color: var(--magenta);
  text-shadow: 0 0 18px rgba(255, 53, 200, 0.55);
}

/* ---------- score ---------- */
.scoreboard {
  display: flex;
  align-items: stretch;
  height: 58px;
  filter: drop-shadow(0 14px 30px rgba(0, 0, 0, 0.55));
}
.score-side {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 128px;
  padding: 0 18px;
  background: linear-gradient(180deg, rgba(14, 24, 44, 0.94), rgba(6, 11, 22, 0.92));
  border: 1px solid rgba(120, 220, 255, 0.22);
  position: relative;
}
.score-side.you {
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  border-right: 0;
}
.score-side.ai {
  flex-direction: row-reverse;
  clip-path: polygon(12px 0, 100% 0, 100% 100%, 0 100%);
  border-left: 0;
}
.score-side::after {
  content: '';
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  opacity: 0.75;
}
.score-side.ai::after { background: linear-gradient(90deg, transparent, var(--magenta), transparent); }
.score-name {
  font-size: 13px;
  letter-spacing: 0.24em;
  font-weight: 700;
  color: #b9cede;
}
.score-num {
  font-family: var(--display);
  font-weight: 900;
  font-size: 32px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  min-width: 24px;
  text-align: center;
  color: #ffffff;
  text-shadow: 0 0 18px currentColor;
}
.score-side.you .score-num { color: var(--cyan-hot); }
.score-side.ai .score-num { color: var(--magenta-hot); }
.score-mid {
  width: 84px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background: linear-gradient(180deg, rgba(12, 20, 38, 0.96), rgba(5, 8, 17, 0.96));
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.vs {
  font-family: var(--display);
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.14em;
  color: #fff;
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.5);
}
.score-rule { width: 28px; height: 1px; background: rgba(255, 255, 255, 0.25); }
.first-to { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); font-weight: 600; }

.utils {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 4px;
}
.icon-btn {
  width: 38px;
  height: 38px;
  border: 1px solid rgba(130, 220, 255, 0.22);
  background: rgba(7, 12, 24, 0.62);
  border-radius: 4px;
  display: grid;
  place-items: center;
  color: #a9c5d8;
  pointer-events: auto;
  backdrop-filter: blur(8px);
  transition: 0.2s ease;
}
.icon-btn svg { width: 18px; height: 18px; fill: currentColor; }
.icon-btn .slash { display: none; stroke: currentColor; stroke-width: 2; fill: none; }
.icon-btn:hover { color: var(--cyan); border-color: rgba(44, 232, 255, 0.6); box-shadow: 0 0 18px rgba(44, 232, 255, 0.15) inset; }
.icon-btn[aria-pressed="true"] { color: #5c7080; }
.icon-btn[aria-pressed="true"] .slash { display: block; }

/* ---------- rally ---------- */
.rally-chip {
  position: absolute;
  top: 94px;
  left: calc(22px + env(safe-area-inset-left));
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 12px 5px 10px;
  border-left: 2px solid var(--cyan);
  background: linear-gradient(90deg, rgba(44, 232, 255, 0.12), transparent);
  font-size: 11px;
  letter-spacing: 0.22em;
  color: #a6c4d6;
  opacity: 0;
  transform: translateX(-10px);
  transition: 0.35s ease;
}
.rally-chip.show { opacity: 1; transform: none; }
.rally-chip b {
  font-family: var(--display);
  font-size: 19px;
  color: #fff;
  letter-spacing: 0;
  text-shadow: 0 0 14px rgba(44, 232, 255, 0.8);
}
.rally-best { font-size: 9px; color: var(--muted); letter-spacing: 0.14em; }

/* ---------- feed ---------- */
.feed {
  position: absolute;
  top: 132px;
  right: calc(24px + env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  width: 300px;
}
.feed-item {
  padding: 6px 12px;
  background: rgba(5, 10, 22, 0.72);
  border-right: 2px solid var(--cyan);
  color: #cfeaf6;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  animation: feedIn 0.22s ease-out both, feedOut 0.4s ease-in 1.4s forwards;
  backdrop-filter: blur(6px);
  text-shadow: 0 0 12px rgba(44, 232, 255, 0.4);
}
.feed-item.gold { border-color: var(--orange); color: #ffd9a8; }
.feed-item.pink { border-color: var(--magenta); color: #ffd1f2; }
@keyframes feedIn { from { opacity: 0; transform: translateX(24px); } }
@keyframes feedOut { to { opacity: 0; transform: translateX(10px); } }

/* ---------- banner ---------- */
.banner {
  position: absolute;
  top: 35%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.94);
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
  width: min(92vw, 900px);
}
.banner.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.banner-main {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(34px, 6vw, 82px);
  letter-spacing: 0.08em;
  line-height: 0.95;
  color: #fff;
  text-shadow:
    0 0 18px rgba(44, 232, 255, 0.7),
    0 0 60px rgba(44, 232, 255, 0.35),
    0 6px 0 rgba(0, 0, 0, 0.35);
}
.banner-sub {
  margin-top: 8px;
  font-size: clamp(11px, 1.4vw, 15px);
  letter-spacing: 0.42em;
  color: #a9d3e4;
  font-weight: 600;
}
.banner.pink .banner-main { color: #ffd8f5; text-shadow: 0 0 20px rgba(255, 53, 200, 0.8), 0 0 70px rgba(255, 53, 200, 0.4); }
.banner.gold .banner-main { color: #fff0d5; text-shadow: 0 0 20px rgba(255, 138, 43, 0.9), 0 0 70px rgba(255, 100, 20, 0.45); }
.banner.lime .banner-main { color: #f0ffd1; text-shadow: 0 0 20px rgba(200, 255, 74, 0.8), 0 0 70px rgba(160, 255, 40, 0.4); }

/* ---------- bottom deck ---------- */
.bottom-deck {
  margin-top: auto;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 22px;
}
.charge-wrap {
  width: min(340px, 32vw);
  padding-bottom: 2px;
}
.charge-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 10px;
  letter-spacing: 0.3em;
  font-weight: 700;
  color: #9eb9ca;
  margin-bottom: 6px;
}
.charge-head span:last-child { font-family: var(--display); font-size: 13px; color: var(--cyan-hot); letter-spacing: 0.04em; }
.charge-track {
  position: relative;
  height: 14px;
  background: rgba(4, 9, 18, 0.82);
  border: 1px solid rgba(90, 190, 230, 0.25);
  clip-path: polygon(0 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  overflow: hidden;
}
.charge-fill {
  position: absolute;
  inset: 2px;
  width: 0%;
  background: linear-gradient(90deg, #0b6e93, var(--cyan) 62%, #eaffff);
  box-shadow: 0 0 18px rgba(44, 232, 255, 0.7);
  transition: width 0.18s ease-out;
}
.charge-fill.hot {
  background: linear-gradient(90deg, #a83a00, var(--orange), #ffe4a3);
  box-shadow: 0 0 22px rgba(255, 138, 43, 0.8);
}
.charge-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(0, 0, 0, 0.5) calc(10% - 1px), rgba(0, 0, 0, 0.5) 10%);
  opacity: 0.55;
}
.charge-ready {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: #1b1000;
  opacity: 0;
  transition: 0.2s;
}
.charge-ready.on { opacity: 1; animation: readyPulse 1s ease-in-out infinite; }
@keyframes readyPulse { 50% { opacity: 0.5; } }
.charge-hint {
  margin-top: 6px;
  font-size: 8.5px;
  letter-spacing: 0.16em;
  color: #617f92;
  font-weight: 600;
}

.powerbar {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  pointer-events: auto;
}
.power {
  position: relative;
  width: 66px;
  height: 66px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 50% 34%, rgba(22, 45, 64, 0.92), rgba(4, 9, 18, 0.94) 70%);
  border: 1px solid rgba(110, 220, 255, 0.34);
  box-shadow: inset 0 0 18px rgba(44, 232, 255, 0.08), 0 10px 30px rgba(0, 0, 0, 0.35);
  transition: transform 0.15s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  overflow: hidden;
}
.power:hover { transform: translateY(-3px); border-color: rgba(150, 245, 255, 0.8); }
.power:active { transform: translateY(0) scale(0.95); }
.pw-ring {
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px dashed rgba(110, 220, 255, 0.2);
}
.pw-glyph {
  position: absolute;
  top: 15px;
  font-family: var(--display);
  font-size: 19px;
  line-height: 1;
  color: var(--cyan-hot);
  text-shadow: 0 0 14px rgba(44, 232, 255, 0.75);
}
.pw-label {
  position: absolute;
  bottom: 13px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: #aac6d6;
}
.pw-key {
  position: absolute;
  top: -1px;
  right: -1px;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #0a1322;
  border: 1px solid rgba(130, 225, 255, 0.4);
  color: #7ca7bb;
  font-size: 8px;
  font-weight: 700;
}
.pw-cd {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(rgba(3, 6, 14, 0.86) calc(var(--p, 0) * 1%), transparent 0);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s;
}
.power.cooling .pw-cd { opacity: 1; }
.power.cooling .pw-glyph { color: #5d7583; text-shadow: none; }
.power.tired { border-color: rgba(255, 110, 110, 0.26); }
.power.tired .pw-glyph { color: #8d5b5b; text-shadow: none; }
.power.ult { border-color: rgba(255, 138, 43, 0.32); }
.power.ult .pw-glyph { color: #ffb262; text-shadow: 0 0 16px rgba(255, 138, 43, 0.7); }
.power.ult.ready {
  border-color: rgba(255, 170, 60, 0.95);
  box-shadow: 0 0 22px rgba(255, 138, 43, 0.5), inset 0 0 24px rgba(255, 138, 43, 0.18);
  animation: ultPulse 1.15s ease-in-out infinite;
}
@keyframes ultPulse {
  50% { box-shadow: 0 0 38px rgba(255, 138, 43, 0.85), inset 0 0 28px rgba(255, 138, 43, 0.3); }
}
.power.flash { animation: powerFlash 0.35s ease-out; }
@keyframes powerFlash {
  0% { box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.8); }
  100% { box-shadow: 0 0 0 24px rgba(255, 255, 255, 0); }
}

.control-hint {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
  margin-top: 12px;
  font-size: 9px;
  letter-spacing: 0.16em;
  color: #6d8b9e;
  font-weight: 600;
  min-height: 16px;
}
.control-hint span { display: flex; align-items: center; gap: 5px; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 17px;
  padding: 0 4px;
  border: 1px solid rgba(130, 220, 255, 0.28);
  border-radius: 2px;
  background: rgba(8, 16, 30, 0.8);
  color: #b9d7e6;
  font-family: var(--body);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.hint-fade { color: #4c7184; transition: opacity 1s ease; }
.hint-fade.gone { opacity: 0; }

.boost-badge {
  position: absolute;
  bottom: 168px;
  right: calc(28px + env(safe-area-inset-right));
  padding: 6px 12px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: #200f00;
  background: linear-gradient(90deg, #ffb03a, #ff7a1a);
  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  opacity: 0;
  transform: translateY(6px);
  transition: 0.25s ease;
  box-shadow: 0 0 30px rgba(255, 138, 43, 0.45);
}
.boost-badge.on { opacity: 1; transform: none; animation: readyPulse 0.9s ease-in-out infinite; }

/* ============================================================
   TOUCH
   ============================================================ */
.touch-ui { display: none; }
body.touch .touch-ui {
  display: block;
  position: absolute;
  inset: 0;
  z-index: 22;
  pointer-events: none;
}
.stick {
  position: absolute;
  left: calc(20px + env(safe-area-inset-left));
  bottom: calc(74px + env(safe-area-inset-bottom));
  width: 104px;
  height: 104px;
  pointer-events: auto;
  touch-action: none;
}
.stick-base {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid rgba(120, 225, 255, 0.28);
  background: radial-gradient(circle, rgba(15, 40, 60, 0.4), rgba(4, 8, 16, 0.55));
  box-shadow: inset 0 0 24px rgba(44, 232, 255, 0.1);
}
.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, rgba(120, 245, 255, 0.55), rgba(8, 30, 46, 0.9));
  border: 1px solid rgba(150, 245, 255, 0.7);
  box-shadow: 0 0 18px rgba(44, 232, 255, 0.35);
  transition: transform 0.05s linear;
}
.stick-label {
  position: absolute;
  left: 0; right: 0; bottom: -15px;
  text-align: center;
  font-size: 8px;
  letter-spacing: 0.3em;
  color: #6d97aa;
  font-weight: 700;
}
.swing-btn {
  position: absolute;
  right: calc(22px + env(safe-area-inset-right));
  bottom: calc(78px + env(safe-area-inset-bottom));
  width: 94px;
  height: 94px;
  border-radius: 50%;
  pointer-events: auto;
  background: radial-gradient(circle at 50% 36%, rgba(255, 90, 200, 0.4), rgba(48, 8, 38, 0.92) 68%);
  border: 1px solid rgba(255, 100, 210, 0.7);
  box-shadow: 0 0 30px rgba(255, 53, 200, 0.28), inset 0 0 24px rgba(255, 53, 200, 0.22);
  color: #ffe4fa;
  font-family: var(--display);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  touch-action: none;
}
.swing-btn:active { transform: scale(0.93); }
body.touch .bottom-deck { padding-right: 0; }
body.touch .powerbar { margin-right: 0; }
body.touch .charge-wrap { display: none; }
body.touch .control-hint { display: none; }
body.touch .boost-badge { bottom: 196px; }
body.touch .rally-chip { top: 88px; }

/* ============================================================
   OVERLAYS
   ============================================================ */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.45s ease, visibility 0.45s;
}
.overlay[hidden] { display: none !important; }

/* ---------- menu ---------- */
.menu {
  justify-content: flex-start;
  padding:
    calc(28px + env(safe-area-inset-top))
    clamp(22px, 5vw, 90px)
    calc(22px + env(safe-area-inset-bottom));
  background:
    linear-gradient(100deg, rgba(4, 3, 12, 0.96) 0%, rgba(4, 4, 14, 0.88) 34%, rgba(4, 4, 14, 0.28) 62%, rgba(4, 4, 14, 0.52) 100%),
    radial-gradient(ellipse at 72% 42%, rgba(255, 40, 180, 0.1), transparent 55%);
  overflow-y: auto;
  pointer-events: auto;
}
.menu.leaving { opacity: 0; visibility: hidden; }
.menu-inner {
  position: relative;
  z-index: 2;
  width: min(650px, 54vw);
  max-width: 100%;
  padding: 10px 0;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.34em;
  color: #86a5b7;
}
.eyebrow em { font-style: normal; color: var(--magenta); }
.eyebrow .dot {
  width: 6px; height: 6px;
  background: var(--lime);
  border-radius: 50%;
  box-shadow: 0 0 12px var(--lime);
  animation: blink 2s ease-in-out infinite;
}
@keyframes blink { 50% { opacity: 0.25; } }

.logo {
  position: relative;
  margin: 14px 0 10px;
  display: flex;
  flex-direction: column;
  font-family: var(--display);
  font-weight: 900;
  line-height: 0.78;
  letter-spacing: -0.035em;
  font-size: clamp(76px, 11.5vw, 168px);
  isolation: isolate;
}
.logo-volt {
  background: linear-gradient(180deg, #ffffff 4%, #bffbff 34%, #2ce8ff 62%, #0a7d9e 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 34px rgba(44, 232, 255, 0.32));
}
.logo-rally {
  align-self: flex-start;
  margin-left: 0.52em;
  background: linear-gradient(180deg, #ffffff 4%, #ffc9ef 30%, #ff35c8 66%, #8d0a66 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 38px rgba(255, 53, 200, 0.3));
}
.logo-ghost {
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(140, 240, 255, 0.14);
  z-index: -1;
  transform: translate(7px, 5px);
}
.tagline {
  margin: 18px 0 0;
  max-width: 440px;
  font-size: clamp(15px, 1.7vw, 20px);
  line-height: 1.4;
  font-weight: 500;
  color: #a9c3d2;
}
.feature-row {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin: 22px 0 24px;
  padding: 12px 0;
  border-top: 1px solid rgba(100, 200, 240, 0.14);
  border-bottom: 1px solid rgba(100, 200, 240, 0.14);
}
.feature-row span {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #bcd6e4;
}
.feature-row i {
  width: 5px; height: 5px;
  transform: rotate(45deg);
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
}
.feature-row span:nth-child(2) i { background: var(--orange); box-shadow: 0 0 10px var(--orange); }
.feature-row span:nth-child(3) i { background: var(--magenta); box-shadow: 0 0 10px var(--magenta); }

.controls-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 26px;
}
.control-card {
  padding: 12px 14px 13px;
  background: linear-gradient(160deg, rgba(16, 30, 50, 0.62), rgba(5, 9, 18, 0.5));
  border: 1px solid rgba(110, 210, 250, 0.12);
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%);
  backdrop-filter: blur(6px);
}
.cc-key {
  display: inline-block;
  padding: 2px 6px;
  border: 1px solid rgba(130, 225, 255, 0.3);
  border-radius: 2px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--cyan-hot);
  margin-bottom: 8px;
}
.control-card b {
  display: block;
  font-family: var(--display);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #eaf8ff;
  margin-bottom: 5px;
}
.control-card small {
  display: block;
  font-size: 11px;
  line-height: 1.35;
  color: #7e9caf;
  font-weight: 500;
}

.menu-cta { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; }
.play-btn {
  position: relative;
  min-width: 205px;
  height: 62px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 0 34px;
  background: linear-gradient(110deg, #a9fdff, #2ce8ff 45%, #16b6d8);
  color: #00141a;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.18em;
  clip-path: polygon(14px 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
  box-shadow: 0 0 40px rgba(44, 232, 255, 0.28);
  overflow: hidden;
  transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.play-btn:hover { transform: translateY(-2px); box-shadow: 0 0 60px rgba(44, 232, 255, 0.6); }
.play-btn:active { transform: translateY(0) scale(0.98); }
.play-btn.small { height: 50px; min-width: 180px; font-size: 13px; }
.play-ico {
  width: 0; height: 0;
  border-top: 8px solid transparent;
  border-bottom: 8px solid transparent;
  border-left: 13px solid #00141a;
}
.play-shine {
  position: absolute;
  top: -40%;
  left: -30%;
  width: 40%;
  height: 180%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.7), transparent);
  transform: rotate(18deg);
  animation: shine 3.4s ease-in-out infinite;
}
@keyframes shine {
  0%, 55% { left: -40%; }
  85%, 100% { left: 130%; }
}
.menu-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #6f8fa2;
}
.meta-dot { width: 3px; height: 3px; background: #4e7083; border-radius: 50%; }

.menu-footer {
  position: absolute;
  left: clamp(22px, 5vw, 90px);
  right: clamp(22px, 5vw, 90px);
  bottom: calc(20px + env(safe-area-inset-bottom));
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: 0.24em;
  color: #486171;
  font-weight: 600;
  z-index: 2;
}
.footer-sound { color: #5a7c90; }
.menu-scroll-hint {
  position: absolute;
  right: clamp(22px, 5vw, 90px);
  top: 50%;
  transform: translateY(-50%) rotate(90deg);
  transform-origin: center;
  font-size: 8px;
  letter-spacing: 0.34em;
  color: rgba(140, 210, 235, 0.4);
  white-space: nowrap;
}
.menu-beam {
  position: absolute;
  width: 46vw;
  height: 140vh;
  top: -20vh;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(44, 232, 255, 0.05), transparent);
  transform: rotate(18deg);
  filter: blur(10px);
}
.beam-a { left: 38%; opacity: 0.8; }
.beam-b { left: 62%; width: 22vw; background: linear-gradient(90deg, transparent, rgba(255, 53, 200, 0.06), transparent); transform: rotate(-24deg); }

/* ---------- result ---------- */
.result {
  background: radial-gradient(ellipse at 50% 45%, rgba(4, 10, 22, 0.72), rgba(3, 4, 12, 0.94));
  backdrop-filter: blur(8px);
  padding: 20px;
}
.result-card {
  width: min(560px, 94vw);
  padding: clamp(24px, 4vw, 42px);
  text-align: center;
  background: linear-gradient(160deg, rgba(13, 24, 44, 0.94), rgba(5, 8, 18, 0.94));
  border: 1px solid rgba(110, 220, 255, 0.22);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6), inset 0 0 80px rgba(44, 232, 255, 0.04);
}
.result-card .eyebrow { justify-content: center; }
.result-card h2 {
  font-family: var(--display);
  font-size: clamp(40px, 8vw, 74px);
  font-weight: 900;
  letter-spacing: 0.06em;
  margin: 12px 0 2px;
  color: #fff;
  text-shadow: 0 0 30px rgba(44, 232, 255, 0.6);
}
.result-card.lose h2 { text-shadow: 0 0 30px rgba(255, 53, 200, 0.6); }
.result-sub { margin: 0 0 22px; font-size: 10px; letter-spacing: 0.28em; color: #83a3b6; font-weight: 600; }
.result-score {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 26px;
  padding: 18px 0 22px;
  border-top: 1px solid rgba(110, 220, 255, 0.12);
  border-bottom: 1px solid rgba(110, 220, 255, 0.12);
}
.result-score div { display: flex; flex-direction: column; gap: 3px; }
.result-score span { font-size: 9px; letter-spacing: 0.26em; color: #7e9caf; font-weight: 700; }
.result-score b { font-family: var(--display); font-size: clamp(34px, 6vw, 52px); line-height: 1; color: var(--cyan-hot); }
.result-score div:last-child b { color: var(--magenta-hot); }
.result-score i { font-style: normal; font-size: 18px; color: #4c6678; }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; margin: 22px 0 26px; background: rgba(110, 220, 255, 0.1); }
.result-stats div { background: #070d1a; padding: 12px 6px; display: flex; flex-direction: column; gap: 4px; }
.result-stats span { font-size: 8px; letter-spacing: 0.18em; color: #6f8fa2; font-weight: 700; }
.result-stats b { font-family: var(--display); font-size: 20px; color: #e8f9ff; }
.result-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.ghost-btn {
  height: 50px;
  padding: 0 22px;
  border: 1px solid rgba(120, 220, 255, 0.26);
  color: #b6d6e6;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  background: rgba(10, 20, 36, 0.5);
  transition: 0.2s ease;
}
.ghost-btn:hover { border-color: var(--cyan); color: var(--cyan-hot); box-shadow: 0 0 24px rgba(44, 232, 255, 0.15) inset; }

/* ---------- pause ---------- */
.pause {
  background: rgba(3, 6, 14, 0.78);
  backdrop-filter: blur(10px);
}
.pause-card { text-align: center; padding: 30px; }
.pause-card .eyebrow { justify-content: center; }
.pause-card h2 {
  font-family: var(--display);
  font-size: clamp(44px, 8vw, 86px);
  font-weight: 900;
  letter-spacing: 0.16em;
  margin: 8px 0 28px;
  color: #fff;
  text-shadow: 0 0 34px rgba(44, 232, 255, 0.45);
}
.pause-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.pause-tip { margin-top: 26px; font-size: 9px; letter-spacing: 0.2em; color: #5d7b8e; font-weight: 600; }

/* ---------- loader ---------- */
.loader {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: #05030c;
  transition: opacity 0.7s ease, visibility 0.7s;
}
.loader.done { opacity: 0; visibility: hidden; }
.loader-mark {
  font-family: var(--display);
  font-weight: 900;
  font-size: 26px;
  letter-spacing: 0.24em;
  color: #dffbff;
  text-shadow: 0 0 30px rgba(44, 232, 255, 0.5);
}
.loader-mark span { color: var(--magenta); text-shadow: 0 0 30px rgba(255, 53, 200, 0.5); }
.loader-bar { width: 220px; height: 2px; background: rgba(80, 170, 210, 0.2); overflow: hidden; }
.loader-bar i { display: block; height: 100%; width: 12%; background: linear-gradient(90deg, transparent, var(--cyan), #fff); animation: load 1.2s ease-in-out infinite; }
@keyframes load { 0% { transform: translateX(-100%); } 100% { transform: translateX(900%); } }
.loader-text { font-size: 8px; letter-spacing: 0.34em; color: #5d7c8e; font-weight: 700; }

.noscript { position: absolute; inset: 0; z-index: 80; display: grid; place-items: center; background: #05030c; color: #fff; text-align: center; padding: 30px; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1080px) {
  .menu-inner { width: min(600px, 62vw); }
  .logo { font-size: clamp(70px, 11vw, 130px); }
  .feed { width: 240px; }
}

@media (max-width: 820px) {
  body { --hud-pad: 16px; }
  .topbar { grid-template-columns: auto 1fr auto; gap: 10px; }
