import * as THREE from 'three';
import { TAU, clamp, lerp, smoothstep, radialTexture } from './utils.js';

const UP = new THREE.Vector3(0, 1, 0);

function capsule(radius, length, mat) {
  const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, 6, 12), mat);
  mesh.castShadow = true;
  return mesh;
}

function makeStrings(radius, color) {
  const positions = [];
  const count = 7;
  for (let i = 1; i < count; i++) {
    const y = -radius + (i / count) * radius * 2;
    const half = Math.sqrt(Math.max(0, radius * radius - y * y));
    positions.push(-half, y, 0, half, y, 0);
    positions.push(y, -half, 0, y, half, 0);
  }
  // clip the vertical lines into a circular-ish bundle by shifting them
  const geo = new THREE.BufferGeometry();
  const arr = [];
  for (let i = 0; i < positions.length; i += 6) {
    const x1 = positions[i], y1 = positions[i + 1];
    const x2 = positions[i + 2], y2 = positions[i + 3];
    if (Math.hypot(x1, y1) > radius || Math.hypot(x2, y2) > radius) continue;
    arr.push(x1, y1, 0, x2, y2, 0);
  }
  geo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  return new THREE.LineSegments(
    geo,
    new THREE.LineBasicMaterial({
      color: new THREE.Color(color).multiplyScalar(1.4),
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
  );
}

export function createAthlete({ tint = 0x2ce8ff, accent = 0x9ffcff, ai = false } = {}) {
  const tintColor = new THREE.Color(tint);
  const accentColor = new THREE.Color(accent);

  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const suitMat = new THREE.MeshStandardMaterial({
    color: 0x07121f,
    metalness: 0.78,
    roughness: 0.3,
    envMapIntensity: 0.9,
  });
  const suitLight = new THREE.MeshStandardMaterial({
    color: 0x102133,
    metalness: 0.6,
    roughness: 0.36,
    envMapIntensity: 0.7,
  });
  const armorMat = new THREE.MeshStandardMaterial({
    color: tintColor.clone().multiplyScalar(0.22),
    emissive: tintColor.clone(),
    emissiveIntensity: 1.35,
    metalness: 0.7,
    roughness: 0.24,
    envMapIntensity: 1.1,
  });
  const accentMat = new THREE.MeshStandardMaterial({
    color: accentColor.clone().multiplyScalar(0.45),
    emissive: accentColor.clone(),
    emissiveIntensity: 2.2,
    metalness: 0.5,
    roughness: 0.2,
  });
  const glowMat = new THREE.MeshBasicMaterial({
    color: tintColor.clone().multiplyScalar(2.7),
    toneMapped: false,
  });
  const whiteGlowMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(1, 1, 1).multiplyScalar(2.2),
    toneMapped: false,
  });
  const darkMetal = new THREE.MeshStandardMaterial({
    color: 0x040810,
    metalness: 0.95,
    roughness: 0.18,
  });

  // ---------------- legs ----------------
  const legs = [];
  for (const side of [-1, 1]) {
    const hip = new THREE.Group();
    hip.position.set(side * 0.17, 0.92, 0);
    body.add(hip);
    const thigh = capsule(0.095, 0.22, suitMat);
    thigh.position.y = -0.19;
    thigh.scale.z = 1.12;
    hip.add(thigh);

    const knee = new THREE.Group();
    knee.position.y = -0.4;
    hip.add(knee);
    const shin = capsule(0.078, 0.22, suitLight);
    shin.position.y = -0.19;
    knee.add(shin);
    const shinGlow = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.18, 0.02), glowMat);
    shinGlow.position.set(0, -0.17, -0.075);
    knee.add(shinGlow);

    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.1, 0.36), suitMat);
    boot.position.set(0, -0.44, -0.08);
    boot.castShadow = true;
    knee.add(boot);
    const bootGlow = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.025, 0.25), glowMat);
    bootGlow.position.set(0, -0.39, -0.09);
    knee.add(bootGlow);
    legs.push({ hip, knee, side });
  }

  // ---------------- torso ----------------
  const hips = new THREE.Mesh(new THREE.CylinderGeometry(0.23, 0.2, 0.2, 12), suitMat);
  hips.position.y = 0.98;
  hips.castShadow = true;
  body.add(hips);

  const torso = capsule(0.25, 0.46, suitMat);
  torso.position.y = 1.27;
  torso.scale.set(1.28, 1.0, 0.82);
  body.add(torso);

  const chestPlate = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.27, 0.08), armorMat);
  chestPlate.position.set(0, 1.35, -0.19);
  chestPlate.castShadow = true;
  body.add(chestPlate);

  const collar = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.018, 6, 20), glowMat);
  collar.rotation.x = Math.PI / 2;
  collar.position.y = 1.52;
  body.add(collar);

  const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.075, 0), accentMat);
  core.position.set(0, 1.4, -0.24);
  body.add(core);
  const coreGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: radialTexture(64, ai ? '255,80,210' : '80,240,255', 0.03),
    color: accentColor.clone().multiplyScalar(1.5),
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  }));
  coreGlow.scale.setScalar(0.7);
  coreGlow.position.set(0, 1.4, -0.27);
  body.add(coreGlow);

  // waist trim
  for (const side of [-1, 1]) {
    const trim = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.18, 0.03), glowMat);
    trim.position.set(side * 0.19, 1.13, -0.13);
    trim.rotation.z = side * 0.18;
    body.add(trim);
  }

  // ---------------- head ----------------
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.075, 0.12, 8), suitLight);
  neck.position.y = 1.62;
  body.add(neck);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.165, 20, 16), suitLight);
  head.position.y = 1.81;
  head.scale.set(0.95, 1.08, 0.92);
  head.castShadow = true;
  body.add(head);

  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.175, 20, 16, 0, TAU, 0, Math.PI * 0.62), darkMetal);
  helmet.position.y = 1.84;
  helmet.scale.set(1.02, 1.02, 1.04);
  helmet.castShadow = true;
  body.add(helmet);

  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.062, 0.055), ai ? whiteGlowMat : accentMat);
  visor.position.set(0, 1.83, -0.142);
  visor.rotation.x = -0.12;
  body.add(visor);

  const visorGlow = glowSpriteLocal(ai ? 0xff8be5 : 0x8ffcff, 0.62, 0.65);
  visorGlow.position.set(0, 1.83, -0.18);
  body.add(visorGlow);

  // crest / antenna
  if (ai) {
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.02, 0.28, 6), darkMetal);
    antenna.position.set(0.13, 2.02, 0.03);
    antenna.rotation.z = -0.3;
    body.add(antenna);
    const tip = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 8), glowMat);
    tip.position.set(0.17, 2.15, 0.03);
    body.add(tip);
  } else {
    const crest = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.13, 0.2), armorMat);
    crest.position.set(0, 1.98, 0.02);
    crest.rotation.x = -0.18;
    body.add(crest);
  }

  // shoulder pads / orbs
  const shoulders = [];
  for (const side of [-1, 1]) {
    const pad = new THREE.Mesh(new THREE.SphereGeometry(0.14, 14, 12), suitMat);
    pad.position.set(side * 0.37, 1.46, 0);
    pad.scale.set(1.1, 0.85, 0.95);
    pad.castShadow = true;
    body.add(pad);
    const cap = new THREE.Mesh(new THREE.TorusGeometry(0.125, 0.016, 5, 16, Math.PI), glowMat);
    cap.position.set(side * 0.39, 1.49, 0);
    cap.rotation.set(0, 0, side > 0 ? -0.2 : Math.PI + 0.2);
    body.add(cap);
    shoulders.push(pad);
  }

  // ---------------- arms ----------------
  function makeArm(side) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.38, 1.45, 0);
    body.add(shoulder);

    const upper = capsule(0.072, 0.2, suitMat);
    upper.position.y = -0.16;
    shoulder.add(upper);
    const upperGlow = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.15, 0.025), glowMat);
    upperGlow.position.set(side * 0.055, -0.16, -0.04);
    shoulder.add(upperGlow);

    const elbow = new THREE.Group();
    elbow.position.y = -0.33;
    shoulder.add(elbow);

    const forearm = capsule(0.06, 0.2, suitLight);
    forearm.position.y = -0.16;
    elbow.add(forearm);
    const forearmGlow = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.13, 0.02), glowMat);
    forearmGlow.position.set(side * 0.04, -0.16, -0.035);
    elbow.add(forearmGlow);

    const hand = new THREE.Group();
    hand.position.y = -0.34;
    elbow.add(hand);
    const fist = new THREE.Mesh(new THREE.SphereGeometry(0.07, 12, 10), darkMetal);
    fist.scale.set(0.9, 1.05, 0.9);
    fist.castShadow = true;
    hand.add(fist);

    return { shoulder, elbow, hand };
  }

  const armL = makeArm(-1);
  armL.shoulder.rotation.set(0.22, 0, -0.32);
  armL.elbow.rotation.set(0.55, 0, 0);

  const armR = makeArm(1);
  armR.shoulder.rotation.set(1.0, -0.25, -0.12);
  armR.elbow.rotation.set(0.55, 0, 0);
  armR.hand.rotation.set(-1.25, 0, 0);

  // ---------------- racket ----------------
  const racket = new THREE.Group();
  armR.hand.add(racket);

  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.038, 0.36, 10), darkMetal);
  grip.position.y = -0.12;
  grip.castShadow = true;
  racket.add(grip);
  for (let i = 0; i < 4; i++) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.039, 0.008, 5, 12), glowMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = -0.24 + i * 0.085;
    racket.add(ring);
  }

  const throat = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), suitMat);
  throat.position.y = 0.12;
  racket.add(throat);

  const hoop = new THREE.Group();
  hoop.position.y = 0.52;
  racket.add(hoop);

  const hoopRadius = 0.36;
  const rim = new THREE.Mesh(new THREE.TorusGeometry(hoopRadius, 0.028, 8, 40), armorMat);
  rim.castShadow = true;
  hoop.add(rim);

  const rimInner = new THREE.Mesh(new THREE.TorusGeometry(hoopRadius - 0.045, 0.009, 5, 36), glowMat);
  hoop.add(rimInner);

  const strings = makeStrings(hoopRadius - 0.02, tint);
  hoop.add(strings);

  const sweetSpot = new THREE.Mesh(
    new THREE.CircleGeometry(0.085, 16),
    new THREE.MeshBasicMaterial({
      color: accentColor.clone().multiplyScalar(2.2),
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
      side: THREE.DoubleSide,
    })
  );
  hoop.add(sweetSpot);

  // energy slash arc, hidden until a swing
  const slashMat = new THREE.MeshBasicMaterial({
    color: tintColor.clone().multiplyScalar(2.4),
    transparent: true,
    opacity: 0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
  const slash = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.72, 32, 1, 0.2, Math.PI * 1.45), slashMat);
  slash.position.y = 0.52;
  slash.rotation.z = -0.4;
  racket.add(slash);

  // racket aura
  const racketGlow = glowSpriteLocal(ai ? 0xff72dc : 0x7ef7ff, 1.5, 0.32);
  racketGlow.position.y = 0.52;
  hoop.add(racketGlow);

  // ---------------- aura / extras ----------------
  const footGlow = new THREE.Mesh(
    new THREE.PlaneGeometry(2.1, 2.1),
    new THREE.MeshBasicMaterial({
      map: radialTexture(128, ai ? '255,60,200' : '50,230,255', 0.02),
      transparent: true,
      opacity: 0.16,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
  );
  footGlow.rotation.x = -Math.PI / 2;
  footGlow.position.y = 0.02;
  root.add(footGlow);

  let halo = null;
  if (ai) {
    halo = new THREE.Mesh(
      new THREE.TorusGeometry(0.29, 0.012, 5, 36),
      new THREE.MeshBasicMaterial({
        color: new THREE.Color(0xff4fd0).multiplyScalar(2.2),
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    halo.position.set(0, 2.02, 0.05);
    halo.rotation.x = 1.2;
    body.add(halo);
  }

  root.traverse((child) => {
    if (child.isMesh && child.material && child.material.isMeshStandardMaterial) {
      child.castShadow = true;
    }
  });
  hoop.traverse((child) => {
    if (child.isMesh) child.castShadow = true;
  });

  // ---------------- runtime ----------------
  const state = {
    swingTime: 0,
    swingDuration: 0.32,
    speed: 0,
    lean: 0,
    superMode: false,
    time: Math.random() * 10,
    baseY: 0,
  };
  const rest = {
    shoulderX: 1.0,
    shoulderY: -0.25,
    shoulderZ: -0.12,
    torsoY: 0,
  };

  function triggerSwing() {
    state.swingTime = state.swingDuration;
  }

  function animate(dt, time, opts = {}) {
    state.time = time;
    const moving = clamp(opts.speed ?? 0, 0, 1);
    const phase = time * (7.5 + moving * 2.5);
    const bob = moving > 0.05 ? Math.abs(Math.sin(phase)) * 0.045 * moving : Math.sin(time * 1.8) * 0.012;
    const breathe = Math.sin(time * 1.5) * 0.01;

    body.position.y = bob + breathe;
    body.rotation.x = lerp(body.rotation.x, -0.055 - moving * 0.055, 1 - Math.exp(-8 * dt));
    const targetLean = clamp((opts.vx ?? 0) * 0.06, -0.22, 0.22);
    body.rotation.z = lerp(body.rotation.z, -targetLean, 1 - Math.exp(-7 * dt));

    // stride
    const stride = Math.sin(phase) * 0.55 * moving;
    legs[0].hip.rotation.x = lerp(legs[0].hip.rotation.x, stride, 1 - Math.exp(-12 * dt));
    legs[1].hip.rotation.x = lerp(legs[1].hip.rotation.x, -stride, 1 - Math.exp(-12 * dt));
    legs[0].knee.rotation.x = Math.max(0, -stride) * 0.9;
    legs[1].knee.rotation.x = Math.max(0, stride) * 0.9;

    // arms idle
    armL.shoulder.rotation.x = 0.22 + Math.sin(phase) * 0.2 * moving;
    armL.shoulder.rotation.z = -0.32 - Math.sin(time * 1.7) * 0.03;

    let p = 0;
    if (state.swingTime > 0) {
      state.swingTime = Math.max(0, state.swingTime - dt);
      p = 1 - state.swingTime / state.swingDuration;
    }
    const wind = smoothstep(0, 0.3, p);
    const strike = smoothstep(0.24, 0.6, p);
    const recover = smoothstep(0.66, 1, p);

    const windup = wind * (1 - recover * 0.7);
    armR.shoulder.rotation.x = rest.shoulderX + windup * 0.22 - strike * 0.45 * (1 - recover);
    armR.shoulder.rotation.y = rest.shoulderY - windup * 0.95 + strike * 2.0 * (1 - recover);
    armR.shoulder.rotation.z = rest.shoulderZ - windup * 0.25 + strike * 0.35;
    armR.elbow.rotation.x = 0.55 + strike * 0.35 * (1 - recover);
    body.rotation.y = lerp(body.rotation.y, -windup * 0.32 + strike * 0.52 * (1 - recover), 0.5);

    // hover / super pulse
    const pulse = 1 + Math.sin(time * 5.2) * 0.08;
    core.scale.setScalar(state.superMode ? pulse * 1.55 : pulse);
    core.rotation.y = time * 1.4;
    core.rotation.x = time * 0.7;
    coreGlow.material.opacity = state.superMode ? 1 : 0.75 + Math.sin(time * 4) * 0.12;
    coreGlow.scale.setScalar(state.superMode ? 1.2 : 0.68);
    chestPlate.material.emissiveIntensity = state.superMode ? 3.2 + Math.sin(time * 12) * 0.8 : 1.35;
    racketGlow.material.opacity = state.superMode ? 0.8 : 0.24 + Math.sin(time * 3) * 0.08;

    slashMat.opacity = p > 0.2 && p < 0.68 ? Math.sin(((p - 0.2) / 0.48) * Math.PI) * (state.superMode ? 0.95 : 0.55) : 0;
    slash.rotation.z = -0.4 + strike * 1.1;

    if (halo) {
      halo.rotation.z = time * 1.1;
      halo.position.y = 2.02 + Math.sin(time * 2) * 0.04;
    }

    visor.scale.x = 1 + (state.superMode ? Math.sin(time * 16) * 0.1 : 0);
    state.p = p;
  }

  function setSuper(active) {
    state.superMode = active;
  }

  const hoopWorld = new THREE.Vector3();
  function getHoopWorld(target = hoopWorld) {
    return hoop.getWorldPosition(target);
  }

  function getSpeed() {
    return state.speed;
  }

  return {
    root,
    body,
    racket,
    hoop,
    armR,
    state,
    tint,
    ai,
    triggerSwing,
    animate,
    setSuper,
    getHoopWorld,
    getSpeed,
    footGlow,
    core,
  };
}

function glowSpriteLocal(color, scale, opacity) {
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: radialTexture(64, color === 0xff8be5 ? '255,140,230' : '140,250,255', 0.02),
    color: new THREE.Color(color),
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  }));
  sprite.scale.setScalar(scale);
  return sprite;
}

import * as THREE from 'three';
import { TAU, rand, easeOutCubic, clamp, glowTexture } from './utils.js';

const PARTICLE_VERT = /* glsl */`
  attribute float aSize;
  attribute vec3 aColor;
  attribute float aAlpha;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = aColor;
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (320.0 / max(0.001, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;

const PARTICLE_FRAG = /* glsl */`
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 c = gl_PointCoord - 0.5;
    float d = length(c);
    if (d > 0.5) discard;
    float a = smoothstep(0.5, 0.0, d);
    a *= a;
    gl_FragColor = vec4(vColor, a * vAlpha);
  }
`;

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.time = 0;

    const MAX = 900;
    this.max = MAX;
    this.cursor = 0;
    this.positions = new Float32Array(MAX * 3);
    this.colors = new Float32Array(MAX * 3);
    this.sizes = new Float32Array(MAX);
    this.alphas = new Float32Array(MAX);
    this.velocities = new Float32Array(MAX * 3);
    this.life = new Float32Array(MAX);
    this.maxLife = new Float32Array(MAX);
    this.drag = new Float32Array(MAX);
    this.gravity = new Float32Array(MAX);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
    this.geometry = geo;
    const mat = new THREE.ShaderMaterial({
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);

    // shockwave pool
    this.ringGeo = new THREE.RingGeometry(0.92, 1.0, 64);
    this.waves = [];
    for (let i = 0; i < 18; i++) {
      const material = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      });
      const mesh = new THREE.Mesh(this.ringGeo, material);
      mesh.visible = false;
      mesh.frustumCulled = false;
      scene.add(mesh);
      this.waves.push({ mesh, material, life: 0, maxLife: 1, maxScale: 3, flat: false, billboard: false });
    }
    this.waveCursor = 0;

    this.trails = [];
  }

  burst(pos, {
    count = 20,
    color = 0x2ce8ff,
    speed = 5,
    speedVar = 3,
    life = 0.6,
    lifeVar = 0.4,
    size = 10,
    sizeVar = 6,
    gravity = -6,
    drag = 1.2,
    upBias = 0.3,
    spread = 1,
  } = {}) {
    const base = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      const idx = this.cursor;
      this.cursor = (this.cursor + 1) % this.max;
      const theta = rand(0, TAU);
      const z = rand(-1, 1);
      const r = Math.sqrt(1 - z * z);
      const sp = speed + rand(-speedVar, speedVar);
      this.positions[idx * 3] = pos.x;
      this.positions[idx * 3 + 1] = pos.y;
      this.positions[idx * 3 + 2] = pos.z;
      this.velocities[idx * 3] = Math.cos(theta) * r * sp * spread;
      this.velocities[idx * 3 + 1] = (z * sp + upBias * speed) * spread;
      this.velocities[idx * 3 + 2] = Math.sin(theta) * r * sp * spread;
      const l = Math.max(0.05, life + rand(-lifeVar, lifeVar));
      this.life[idx] = l;
      this.maxLife[idx] = l;
      this.drag[idx] = drag;
      this.gravity[idx] = gravity;
      const cc = base.clone();
      cc.offsetHSL(rand(-0.05, 0.05), rand(-0.15, 0.1), rand(-0.05, 0.18));
      this.colors[idx * 3] = cc.r;
      this.colors[idx * 3 + 1] = cc.g;
      this.colors[idx * 3 + 2] = cc.b;
      this.sizes[idx] = size + rand(-sizeVar, sizeVar);
      this.alphas[idx] = 1;
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }

  wave(pos, {
    color = 0x2ce8ff,
    maxScale = 3,
    duration = 0.5,
    flat = false,
    opacity = 0.9,
    rotation = 0,
  } = {}) {
    const slot = this.waves[this.waveCursor];
    this.waveCursor = (this.waveCursor + 1) % this.waves.length;
    slot.mesh.position.copy(pos);
    slot.mesh.visible = true;
    slot.mesh.scale.setScalar(0.2);
    slot.material.color.set(color).multiplyScalar(1.8);
    slot.material.opacity = opacity;
    slot.life = duration;
    slot.maxLife = duration;
    slot.maxScale = maxScale;
    slot.flat = flat;
    slot.opacity = opacity;
    if (flat) {
      slot.mesh.quaternion.identity();
      slot.mesh.rotation.x = -Math.PI / 2;
      slot.mesh.rotation.z = rotation;
    } else {
      slot.mesh.quaternion.copy(this.camera.quaternion);
      slot.mesh.rotateZ(rotation);
    }
  }

  update(dt) {
    this.time += dt;
    const dirty = { pos: false, color: false, size: false, alpha: false };
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.alphas[i] = 0;
        this.sizes[i] = 0;
        dirty.alpha = true;
        dirty.size = true;
        continue;
      }
      const d = Math.max(0, 1 - this.drag[i] * dt);
      this.velocities[i * 3] *= d;
      this.velocities[i * 3 + 1] = this.velocities[i * 3 + 1] * d + this.gravity[i] * dt;
      this.velocities[i * 3 + 2] *= d;
      this.positions[i * 3] += this.velocities[i * 3] * dt;
      this.positions[i * 3 + 1] += this.velocities[i * 3 + 1] * dt;
      this.positions[i * 3 + 2] += this.velocities[i * 3 + 2] * dt;
      const k = this.life[i] / this.maxLife[i];
      this.alphas[i] = k * k;
      dirty.pos = true;
      dirty.alpha = true;
    }
    if (dirty.pos) this.geometry.attributes.position.needsUpdate = true;
    if (dirty.alpha) this.geometry.attributes.aAlpha.needsUpdate = true;
    if (dirty.size) this.geometry.attributes.aSize.needsUpdate = true;
    if (dirty.color) this.geometry.attributes.aColor.needsUpdate = true;

    for (const wave of this.waves) {
      if (wave.life <= 0) continue;
      wave.life -= dt;
      const t = clamp(1 - wave.life / wave.maxLife, 0, 1);
      const scale = 0.2 + easeOutCubic(t) * wave.maxScale;
      wave.mesh.scale.setScalar(scale);
      wave.material.opacity = wave.opacity * Math.pow(1 - t, 1.8);
      if (wave.life <= 0) wave.mesh.visible = false;
    }

    for (const trail of this.trails) trail.update(dt);
  }

  createMarker(color, radius = 0.6) {
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).multiplyScalar(1.8),
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
      toneMapped: false,
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(radius * 0.8, radius, 48), mat);
    ring.rotation.x = -Math.PI / 2;
    group.add(ring);
    const inner = new THREE.Mesh(new THREE.RingGeometry(radius * 0.25, radius * 0.31, 32), mat);
    inner.rotation.x = -Math.PI / 2;
    group.add(inner);

    for (let i = 0; i < 4; i++) {
      const tick = new THREE.Mesh(new THREE.PlaneGeometry(radius * 0.08, radius * 0.32), mat);
      tick.rotation.x = -Math.PI / 2;
      tick.rotation.z = (i / 4) * TAU;
      tick.position.set(Math.cos((i / 4) * TAU) * radius * 1.18, 0, Math.sin((i / 4) * TAU) * radius * 1.18);
      group.add(tick);
    }

    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(radius * 0.02, radius * 0.16, 1.4, 8, 1, true),
      new THREE.MeshBasicMaterial({
        color: new THREE.Color(color).multiplyScalar(0.7),
        transparent: true,
        opacity: 0.16,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      })
    );
    beam.position.y = 0.7;
    group.add(beam);
    group.position.y = 0.025;
    group.visible = false;
    this.scene.add(group);
    return {
      group,
      material: mat,
      setVisible(v) { group.visible = v; },
      setPosition(x, z) { group.position.set(x, 0.025, z); },
      setIntensity(v) {
        mat.opacity = clamp(v, 0, 1) * 0.9;
        beam.material.opacity = clamp(v, 0, 1) * 0.2;
      },
      pulse(time, speed = 3) {
        const s = 1 + Math.sin(time * speed) * 0.06;
        group.scale.set(s, 1, s);
        ring.rotation.z = time * 0.6;
      },
    };
  }

  createTrail({ color = 0x2ce8ff, length = 30, size = 0.24 } = {}) {
    const positions = new Float32Array(length * 3);
    const colors = new Float32Array(length * 3);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const line = new THREE.Line(geo, new THREE.LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    }));
    line.frustumCulled = false;
    this.scene.add(line);

    const pGeo = new THREE.BufferGeometry();
    pGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    pGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const points = new THREE.Points(pGeo, new THREE.PointsMaterial({
      size,
      map: glowTexture(),
      vertexColors: true,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
      toneMapped: false,
    }));
    points.frustumCulled = false;
    this.scene.add(points);

    const base = new THREE.Color(color);
    const history = new Array(length).fill(null).map(() => new THREE.Vector3());
    const head = { x: 0, y: 0, z: 0 };
    let has = false;
    let active = true;

    const trail = {
      line,
      points,
      setActive(v) {
        active = v;
        line.visible = v;
        points.visible = v;
        if (!v) has = false;
      },
      setColor(c) {
        base.set(c);
      },
      push(pos) {
        if (!active) return;
        if (!has) {
          for (const p of history) p.copy(pos);
          has = true;
        } else {
          for (let i = length - 1; i > 0; i--) history[i].copy(history[i - 1]);
          history[0].copy(pos);
        }
        for (let i = 0; i < length; i++) {
          const p = history[i];
          positions[i * 3] = p.x;
          positions[i * 3 + 1] = p.y;
          positions[i * 3 + 2] = p.z;
          const k = Math.pow(1 - i / length, 2.2);
          colors[i * 3] = base.r * k;
          colors[i * 3 + 1] = base.g * k;
          colors[i * 3 + 2] = base.b * k;
        }
        geo.attributes.position.needsUpdate = true;
        geo.attributes.color.needsUpdate = true;
        pGeo.attributes.position.needsUpdate = true;
        pGeo.attributes.color.needsUpdate = true;
      },
      update(dt) {
        if (!active) return;
        // gently collapse the tail when the ball stops moving
        for (let i = 1; i < length; i++) {
          const p = history[i];
          p.lerp(history[i - 1], dt * 1.8);
        }
        for (let i = 0; i < length; i++) {
          const p = history[i];
          positions[i * 3] = p.x;
          positions[i * 3 + 1] = p.y;
          positions[i * 3 + 2] = p.z;
        }
        geo.attributes.position.needsUpdate = true;
        pGeo.attributes.position.needsUpdate = true;
      },
    };
    this.trails.push(trail);
    return trail;
  }
}

content.text:
Now main.js — the biggest part. Let's design carefully and implement.

Imports:
```js
import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { buildWorld } from './world.js';
import { createAthlete } from './athlete.js';
import { Effects } from './effects.js';
import { AudioEngine } from './audio.js';
import { COURT, clamp, damp, rand, lerp, ballisticVelocity, predictLanding, easeOutCubic, wrap, smoothstep } from './utils.js';
```

Wait OutputPass before vignette; ShaderPass imported. Fine.

Setup:
```js
const isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
if (isTouch) document.body.classList.add('touch');
```
But hybrid laptops with touch will get touch UI while mouse also works; okay. Maybe show touch UI only when `maxTouchPoints > 0 && innerWidth < 1024`. Let's do `isTouch = (navigator.maxTouchPoints > 0 && window.innerWidth <= 1024) || matchMedia('(pointer: coarse)').matches`. On capture mobile 390x844: matchMedia pointer coarse? Playwright newPage not mobile emulation, so maxTouchPoints 0 and pointer fine. Desktop screenshot might show no touch UI. The mobile screenshot would just be narrow desktop; then touch controls won't show. The verification might use viewport only. We should base on viewport width too: `innerWidth <= 820` → add touch. That ensures mobile screenshot has mobile controls. But if resized desktop to narrow, still shows touch; acceptable. Use `const isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0 || innerWidth <= 820;`.

Renderer config. Shadows.

Load flow:
- The loader should hide once setup done and fonts loaded maybe. `requestAnimationFrame(() => loader.classList.add('done'))`.
- Use `document.fonts.ready` to ensure fonts; then hide.

Initial camera menu:
- camera.position.set(6.5,4.6,14.5); lookAt (0,1.2,-2). Update in menu orbit. Let's choose orbit with x oscillating 5-8, z 14-16, y 4.2-5.0, target (-1,1.2,-2) to show court right of menu. Menu content covers left 54%, so court appears on right. Good.
- menu time t; camera x = 7.4 + sin(t*0.09)*2.2; y = 4.7+sin(t*0.13)*0.4; z = 14 + cos(t*0.075)*1.4. lookAt(0.5,1.1,-2.5). This should look toward center, court occupying center/right.

Player/AI positions in menu: player (0, 8.35) idle, AI (sin*1.2, -8.35).
Ball in menu: floating over net, orbit; mesh and glow visible. Set ball pos (sin(t)*2.8, 1.4+sin(t*1.3)*.4, 0.4). Active false but visible. Trail off.

HUD hidden during menu (`.hud` no live). Touch UI hidden because hud? touch UI is separate; CSS body.touch displays always, even menu. Need hide touch UI unless playing. Add `#touchUI` visibility controlled with `.active` class; default display none? Currently body.touch .touch-ui displays block always. We should add `.touch-ui {opacity:0; visibility:hidden; transition}` and `body.touch .touch-ui.playing {opacity:1;visibility:visible}`. Or add class when HUD live. Modify CSS: default `.touch-ui{display:none}`; `body.touch .touch-ui {display:block; opacity:0; visibility:hidden}`; `body.touch .touch-ui.on{opacity:1;visibility:visible}`. Then JS add/remove `on` with HUD. We'll adjust CSS later.

Game state definitions:

```js
const G = {
  phase:'menu',
  prevPhase:'menu',
  scores:{player:0,ai:0},
  rally:0, bestRally:0, perfects:0, smashes:0,
  charge:0,
  superArmed:false,
  dashCd:0, warpCd:0, warpTime:0,
  serveTimer:0, pointTimer:0, server:'player',
  swingCd:0,
  pointReason:'',
  matchOver:false,
  startTime:0,
  menu:true,
  pausedFrom:null,
  shotCount:0,
  aiSurge:0,
  aiSurgeCd:0,
  hitStop:0,
  flashTimer:0,
};
```
`phase` values: menu, serve, rally, point, over, paused.

Ball object:
```js
const ball = {
 pos: new THREE.Vector3(0,1.2,0),
 vel: new THREE.Vector3(),
 active:false,
 visible:true,
 lastHitter:'player',
 bounces:0,
 superShot:false,
 hot:false,
 lastLanding:null,
 landingTimer:0,
};
```
`ballMesh` group. `ballSphere` emissive material; `ballGlow` sprite; `ballLight`. Attach group to scene.

Ball material emissive colors change per hitter:
- player: cyan, ai: magenta, super: orange.
Set color each hit.
`setBallTint(color, hot)` updates material.emissive, glow material color, light color, trail color.

Glow sprite size 1.3; on super 2.2.

Ball light intensity 18 distance 12 decay 2. In three r184, `PointLight(color, intensity, distance, decay)`. Good.

Ball shadow? Add a fake shadow circle under ball using `Mesh(CircleGeometry(.3), MeshBasicMaterial black transparent opacity .35)` rotated flat. Update y=0.02 and scale based on height, opacity. Or use real castShadow from ball; sphere castShadow true. Real shadow from directional light needs shadow map. We'll enable. But ball moving fast may shadow okay. Add a fake "glow disc" under ball instead, colored, useful landing visual. A radial glow plane at floor tracking ball x,z with opacity depending on height. Use additive tinted plane. Nice.

Player/AI:
```js
const player = createAthlete({tint:0x2ce8ff, accent:0x9ffcff});
const ai = createAthlete({tint:0xff35c8, accent:0xff9fe4, ai:true});
scene.add(player.root); scene.add(ai.root);
player.root.position.set(0,0,COURT.playerZ);
ai.root.rotation.y = Math.PI; ai.root.position.set(0,0,COURT.aiZ);
```

Afterimages: create ghost clones:
```js
function makeGhost() {
 const ghost = player.root.clone(true);
 ghost.traverse(child => { if(child.isMesh){ child.material = new THREE.MeshBasicMaterial({color:0x2ce8ff, transparent:true, opacity:0.18, blending:Additive, depthWrite:false, toneMapped:false}); child.castShadow=false; } if(child.isSprite) child.visible=false; });
 ghost.visible=false; scene.add(ghost)
}
```
But cloning includes player.root with footGlow etc. Fine. However `clone(true)` shares geometry; materials replaced with a single shared material. Sprites share? Set invisible. Use 2 ghosts. `ghost.userData.life`. On dash, position & rotation copy; show; fade opacity; update each frame.

Need to ensure clone is taken after model built and before animations? It clones group with current transforms; when we set ghost.position/rotation it aligns root. Body internal pose is at creation; not matching current legs. Good enough silhouette.

Input handling:
```js
const keys = new Set();
const input = { pointerActive:false, touchX:0, touchZ:0, lastAxis:1 };
