  }

  bind() {
    $('playBtn')?.addEventListener('click', () => this.cb.onPlay?.());
    $('againBtn')?.addEventListener('click', () => this.cb.onPlay?.());
    $('menuBtn')?.addEventListener('click', () => this.cb.onMenu?.());
    this.pauseBtn?.addEventListener('click', () => this.cb.onPause?.());
    $('resumeBtn')?.addEventListener('click', () => this.cb.onPause?.());
    $('restartBtn')?.addEventListener('click', () => this.cb.onRestart?.());
    this.muteBtn?.addEventListener('click', () => this.cb.onMute?.());
    this.pw.dash.btn?.addEventListener('click', () => this.cb.onPower?.('dash'));
    this.pw.warp.btn?.addEventListener('click', () => this.cb.onPower?.('warp'));
    this.pw.smash.btn?.addEventListener('click', () => this.cb.onPower?.('smash'));
    $('swingBtn')?.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      this.cb.onSwing?.();
    });
  }

  setTouch(enabled) {
    this.touchEnabled = enabled;
    document.body.classList.toggle('touch', enabled);
  }

  showMenu() {
    this.menu.hidden = false;
    this.menu.classList.remove('leaving');
    this.hideHUD();
    this.setTouchOn(false);
    this.hideResult();
    this.hidePause();
  }

  hideMenu() {
    this.menu.classList.add('leaving');
    this.setTouchOn(this.touchEnabled);
  }

  showHUD() { this.hud.classList.add('live'); }
  hideHUD() { this.hud.classList.remove('live'); }
  setTouchOn(on) { this.touchUI.classList.toggle('on', Boolean(on && this.touchEnabled)); }

  showResult({ win, playerScore, aiScore, bestRally, perfects, smashes }) {
    this.result.hidden = false;
    this.resultCard.classList.toggle('lose', !win);
    $('resultTitle').textContent = win ? 'VICTORY' : 'DEFEAT';
    $('resultSub').textContent = win ? 'THE ARENA REMEMBERS YOUR NAME' : 'VEXA KEEPS THE CROWN — FOR NOW';
    $('resultEyebrow').textContent = win ? 'MATCH COMPLETE' : 'MATCH COMPLETE';
    $('resultPlayer').textContent = String(playerScore);
    $('resultAI').textContent = String(aiScore);
    $('statRally').textContent = String(bestRally);
    $('statPerfect').textContent = String(perfects);
    $('statSmash').textContent = String(smashes);
  }

  hideResult() { this.result.hidden = true; }
  showPause() { this.pause.hidden = false; }
  hidePause() { this.pause.hidden = true; }

  banner(main, sub = '', tone = '', duration = 1.5) {
    this.bannerMain.textContent = main;
    this.bannerSub.textContent = sub;
    this.banner.className = `banner show ${tone}`.trim();
    this.bannerTimer = duration;
  }

  clearBanner() {
    this.banner.classList.remove('show');
    this.bannerTimer = 0;
  }

  feed(text, tone = '') {
    const item = document.createElement('div');
    item.className = `feed-item ${tone}`.trim();
    item.textContent = text;
    this.feedRoot.appendChild(item);
    while (this.feedRoot.children.length > 4) this.feedRoot.firstElementChild.remove();
    setTimeout(() => item.remove(), 1900);
  }

  flash(kind = 'fire') {
    this.fxFlash.classList.remove('fire', 'warp');
    // force the animation to restart even when re-triggered in the same frame
    void this.fxFlash.offsetWidth;
    this.fxFlash.classList.add(kind);
  }

  tint(on) {
    this.fxTint.classList.toggle('on', Boolean(on));
  }

  setMuted(muted) {
    this.muteBtn.setAttribute('aria-pressed', String(muted));
  }

  setScores(player, ai) {
    this.scorePlayer.textContent = String(player);
    this.scoreAI.textContent = String(ai);
  }

  setCharge(charge) {
    const pct = Math.round(charge);
    this.chargeFill.style.width = `${pct}%`;
    this.chargePct.textContent = `${pct}%`;
  }

  setCooldown(entry, remaining, total, tired = false) {
    if (remaining > 0.01) {
      entry.btn.classList.add('cooling');
      entry.cd.style.setProperty('--p', String((remaining / total) * 100));
    } else {
      entry.btn.classList.remove('cooling');
      entry.cd.style.setProperty('--p', '0');
    }
    entry.btn.classList.toggle('tired', Boolean(tired));
  }

  update(dt, state) {
    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt;
      if (this.bannerTimer <= 0) this.banner.classList.remove('show');
    }

    const l = this.last;
    if (state.playerScore !== l.playerScore || state.aiScore !== l.aiScore) {
      this.setScores(state.playerScore, state.aiScore);
      l.playerScore = state.playerScore;
      l.aiScore = state.aiScore;
    }
    if (state.charge !== l.charge) {
      this.setCharge(state.charge);
      l.charge = state.charge;
    }
    if (state.dashCd !== l.dash) {
      this.setCooldown(this.pw.dash, state.dashCd, 3.2);
      l.dash = state.dashCd;
    }
    if (state.warpCd !== l.warp) {
      this.setCooldown(this.pw.warp, state.warpCd, 9, state.charge < 35);
      l.warp = state.warpCd;
    }
    const smashReady = state.charge >= 100 || state.superArmed;
    if (smashReady !== l.smashReady) {
      this.pw.smash.btn.classList.toggle('ready', smashReady);
      l.smashReady = smashReady;
    }
    if (state.superArmed !== l.armed) {
      this.boostBadge.classList.toggle('on', Boolean(state.superArmed));
      this.chargeFill.classList.toggle('hot', Boolean(state.superArmed || state.charge >= 100));
      this.chargeReady.textContent = state.superArmed ? 'SMASH ARMED — HIT THE STAR' : 'R — SUPER SMASH';
      this.chargeReady.classList.toggle('on', smashReady);
      l.armed = state.superArmed;
    }
    if (state.rally !== l.rally || state.phase !== l.phase) {
      this.rallyChip.classList.toggle('show', state.rally > 0 && (state.phase === 'rally' || state.phase === 'serve'));
      this.rallyCount.textContent = String(state.rally);
      this.rallyBest.textContent = state.bestRally > 0 ? `BEST ${state.bestRally}` : '';
      l.rally = state.rally;
      l.phase = state.phase;
    }
    this.hintFade.classList.toggle('gone', state.shots > 0 || state.elapsed > 22);
  }

  loaderDone() {
    this.loader.classList.add('done');
  }

  error(message) {
    this.loaderText.textContent = message;
  }
}

import { clamp } from './utils.js';

const ACTIVE_PHASES = new Set(['serve', 'rally', 'point']);

export class Input {
  constructor({
    canvas, stick, knob,
    onSwing, onPower, onPause, onMute, onStart, onPointer, getPhase,
  }) {
    this.canvas = canvas;
    this.stick = stick;
    this.knob = knob;
    this.onSwing = onSwing;
    this.onPower = onPower;
    this.onPause = onPause;
    this.onMute = onMute;
    this.onStart = onStart;
    this.onPointer = onPointer;
    this.getPhase = getPhase;

    this.keys = new Set();
    this.pointer = { x: 0, y: 0, active: false };
    this.touch = { x: 0, y: 0, active: false };
    this.stickPointer = null;
    this.swinging = false;

    this.bind();
  }

  active() {
    return ACTIVE_PHASES.has(this.getPhase());
  }

  bind() {
    window.addEventListener('keydown', (event) => {
      const code = event.code;
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(code)) event.preventDefault();
      if (event.repeat) return;
      this.keys.add(code);

      if (code === 'Space' || code === 'Enter') {
        if (this.getPhase() === 'menu') {
          this.onStart?.();
          return;
        }
      }
      if (code === 'Space') {
        if (this.active()) this.requestSwing();
        return;
      }
      if (code === 'KeyQ' && this.active()) return this.onPower?.('dash');
      if (code === 'KeyE' && this.active()) return this.onPower?.('warp');
      if (code === 'KeyR' && this.active()) return this.onPower?.('smash');
      if (code === 'KeyM') return this.onMute?.();
      if (code === 'Escape' || code === 'KeyP') {
        const phase = this.getPhase();
        if (phase !== 'menu' && phase !== 'over') this.onPause?.();
      }
    });

    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code);
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touch.active = false;
      this.touch.x = 0;
      this.touch.y = 0;
      this.resetStick();
    });

    this.canvas.addEventListener('pointermove', (event) => {
      if (event.pointerType === 'touch') return;
      const rect = this.canvas.getBoundingClientRect();
      const nx = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      const ny = ((event.clientY - rect.top) / rect.height) * 2 - 1;
      this.pointer.active = true;
      this.pointer.x = clamp(nx, -1.2, 1.2);
      this.pointer.y = clamp(ny, -1.2, 1.2);
      if (this.active()) this.onPointer?.(this.pointer.x, this.pointer.y);
    });

    this.canvas.addEventListener('pointerdown', (event) => {
      if (event.button !== undefined && event.button !== 0) return;
      if (event.pointerType === 'touch') event.preventDefault();
      if (this.active()) this.requestSwing();
    });

    this.canvas.addEventListener('contextmenu', (event) => event.preventDefault());

    if (this.stick) this.bindStick();
  }

  bindStick() {
    const update = (event) => {
      const rect = this.stick.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = (event.clientX - cx) / (rect.width * 0.42);
      let dy = (event.clientY - cy) / (rect.height * 0.42);
      const length = Math.hypot(dx, dy);
      if (length > 1) {
        dx /= length;
        dy /= length;
      }
      this.touch.x = dx;
      this.touch.y = dy;
      this.touch.active = true;
      this.knob.style.transform = `translate(${dx * 27}px, ${dy * 27}px)`;
    };

    this.stick.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      this.stickPointer = event.pointerId;
      this.stick.setPointerCapture(event.pointerId);
      update(event);
    });
    this.stick.addEventListener('pointermove', (event) => {
      if (event.pointerId !== this.stickPointer) return;
      event.preventDefault();
      update(event);
    });
    const release = (event) => {
      if (event.pointerId !== this.stickPointer) return;
      this.stickPointer = null;
      this.touch.active = false;
      this.touch.x = 0;
      this.touch.y = 0;
      this.resetStick();
    };
    this.stick.addEventListener('pointerup', release);
    this.stick.addEventListener('pointercancel', release);
    this.stick.addEventListener('lostpointercapture', release);
  }

  resetStick() {
    if (this.knob) this.knob.style.transform = 'translate(0px, 0px)';
  }

  requestSwing() {
    if (this.swinging) return;
    this.swinging = true;
    this.onSwing?.();
  }

  consumeSwing() {
    this.swinging = false;
  }

  reset() {
    this.keys.clear();
    this.touch.active = false;
    this.touch.x = 0;
    this.touch.y = 0;
    this.resetStick();
    this.swinging = false;
  }
}

import * as THREE from 'three';
import {
  COURT, clamp, damp, rand, lerp, sign, approach,
  ballisticVelocity, predictLanding,
} from './utils.js';
import { AudioEngine } from './audio.js';
import { Input } from './input.js';

const CYAN = 0x2ce8ff;
const MAGENTA = 0xff35c8;
const ORANGE = 0xff8a2b;
const LIME = 0xc8ff4a;
const GRAVITY = COURT.gravity;
const R = COURT.ballR;

const tmpV = new THREE.Vector3();
const tmpV2 = new THREE.Vector3();
const prevPos = new THREE.Vector3();
const fromPos = new THREE.Vector3();
const targetPos = new THREE.Vector3();

export function createGame({ stage, ui, isTouch = false }) {
  const {
    player, ai, camera, effects, trail,
    aimMarker, landingMarker, aiLandingMarker,
  } = stage;

  const audio = new AudioEngine();
  const G = {
    phase: 'menu',
    pausedFrom: null,
    playerScore: 0,
    aiScore: 0,
    charge: 34,
    dashCd: 0,
    warpCd: 0,
    warpTime: 0,
    superArmed: false,
    rally: 0,
    bestRally: 0,
    perfects: 0,
    smashes: 0,
    shots: 0,
    elapsed: 0,
    server: 'player',
    serveTimer: 0,
    pointTimer: 0,
    shake: 0,
    fovPunch: 0,
    aiStun: 0,
    aiKnock: 0,
    aiSurgeVisual: 0,
    aiSurgeCd: 0,
    swingCd: 0,
    playerHitLock: 0,
    muted: false,
    initialServe: true,
    aimColor: LIME,
  };

  const ball = {
    pos: new THREE.Vector3(0, 1.3, 0.5),
    vel: new THREE.Vector3(),
    active: false,
    bounces: 0,
    lastHitter: 'player',
    superShot: false,
  };

  const move = {
    x: 0,
    z: COURT.playerZ,
    tx: 0,
    tz: COURT.playerZ,
    vx: 0,
    vz: 0,
  };

  let aiX = 0;
  let aiBias = 0;
  let aiSwingCd = 0;
  let predictTimer = 0;
  let landInfo = null;
  let aiLandInfo = null;
  let bloomBase = isTouch ? 0.85 : 1.0;
  let initialised = false;

  const input = new Input({
    canvas: document.getElementById('scene'),
    stick: document.getElementById('stick'),
    knob: document.getElementById('stickKnob'),
    getPhase: () => G.phase,
    onSwing: () => swing(),
    onPower: (power) => usePower(power),
    onPause: () => togglePause(),
    onMute: () => toggleMute(),
    onStart: () => startMatch(),
    onPointer: (nx, ny) => {
      if (G.phase !== 'serve' && G.phase !== 'rally' && G.phase !== 'point') return;
      move.tx = clamp(nx * 5.0, -4.78, 4.78);
      move.tz = clamp(COURT.playerZ + ny * 2.7, 4.9, 9.45);
    },
  });

  // ---------------------------------------------------------------- lifecycle
  function startMatch() {
    audio.start();
    audio.setPaused(false);
    G.phase = 'serve';
    G.playerScore = 0;
    G.aiScore = 0;
    G.charge = 34;
    G.dashCd = 0;
    G.warpCd = 0;
    G.warpTime = 0;
    G.warpVisual = false;
    G.superArmed = false;
    G.rally = 0;
    G.bestRally = 0;
    G.perfects = 0;
    G.smashes = 0;
    G.shots = 0;
    G.shake = 0;
    G.fovPunch = 0;
    G.aiStun = 0;
    G.aiKnock = 0;
    G.aiSurgeVisual = 0;
    G.aiSurgeCd = 0;
    G.swingCd = 0;
    G.playerHitLock = 0;
    G.server = 'player';
    G.initialServe = true;
    G.aimColor = LIME;
    aiX = 0;
    aiBias = 0;
    aiSwingCd = 0;
    move.x = move.tx = 0;
    move.z = move.tz = COURT.playerZ;
    player.root.position.set(move.x, 0, move.z);
    ai.root.position.set(aiX, 0, COURT.aiZ);
    player.setSuper(false);
    ai.setSuper(false);
    stage.world.setWarp(false);
    stage.bloom.strength = bloomBase;
    ui.tint(false);
    ui.hideMenu();
    ui.hideResult();
    ui.hidePause();
    ui.showHUD();
    ui.setTouchOn(isTouch);
    ui.clearBanner();
    ui.setScores(0, 0);
    ui.setCharge(G.charge);
    ui.feed('MATCH START — YOU SERVE');
    input.reset();
    beginServe(false);
  }

  function goMenu() {
    G.phase = 'menu';
    G.warpTime = 0;
    G.superArmed = false;
    G.aiStun = 0;
    player.setSuper(false);
    ai.setSuper(false);
    stage.world.setWarp(false);
    stage.bloom.strength = bloomBase;
    ui.tint(false);
    audio.setWarp(false);
    audio.setPaused(true);
    ui.showMenu();
    ui.hideResult();
    ui.hidePause();
    aimMarker.setVisible(false);
    landingMarker.setVisible(false);
    aiLandingMarker.setVisible(false);
    stage.ballGroup.visible = true;
    stage.floorGlow.visible = true;
    stage.trail.setActive(false);
    input.reset();
  }

  function togglePause() {
    if (G.phase === 'menu' || G.phase === 'over') return;
    if (G.phase === 'paused') {
      G.phase = G.pausedFrom || 'rally';
      G.pausedFrom = null;
      ui.hidePause();
      audio.setPaused(false);
      input.reset();
      return;
    }
    G.pausedFrom = G.phase;
    G.phase = 'paused';
    ui.showPause();
    audio.setPaused(true);
    input.reset();
  }

  function toggleMute() {
    G.muted = !G.muted;
    audio.setMuted(G.muted);
    ui.setMuted(G.muted);
  }

  function beginServe(withBanner = true) {
    G.phase = 'serve';
    G.serveTimer = G.initialServe ? 0.62 : 0.95;
    G.rally = 0;
    ball.active = false;
    ball.bounces = 0;
    ball.lastHitter = G.server;
    ball.superShot = false;
    aiSwingCd = 0;
    aiBias = rand(-0.35, 0.35);
    move.x = move.tx = 0;
    move.z = move.tz = COURT.playerZ;
    aiX = 0;
    player.root.position.set(move.x, 0, move.z);
    ai.root.position.set(aiX, 0, COURT.aiZ);
    player.setSuper(G.superArmed);
    ai.setSuper(false);
    stage.ballGroup.visible = true;
    stage.floorGlow.visible = true;
    stage.trail.setActive(false);
    setServeBallPosition();
    stage.setBallTint(G.server === 'player' ? CYAN : MAGENTA, false);
    aimMarker.setVisible(false);
    landingMarker.setVisible(false);
    aiLandingMarker.setVisible(false);
    if (withBanner) {
      ui.banner('SERVE', `${G.server === 'player' ? 'YOU' : 'VEXA'} TO SERVE`, G.server === 'player' ? 'lime' : 'pink', 0.9);
    }
    G.initialServe = false;
  }

  function setServeBallPosition() {
    if (G.server === 'player') {
      ball.pos.set(move.x + 0.28, 1.44 + Math.sin(G.elapsed * 3) * 0.05, move.z - 0.92);
    } else {
      ball.pos.set(aiX - 0.25, 1.44 + Math.sin(G.elapsed * 3) * 0.05, COURT.aiZ + 0.92);
    }
    stage.syncBall(ball.pos, G.elapsed);
  }

  function launchServe() {
    if (G.server === 'player') {
      fromPos.copy(ball.pos);
      targetPos.set(rand(-2.7, 2.7), R, rand(-8.9, -6.9));
    } else {
      fromPos.copy(ball.pos);
      targetPos.set(rand(-2.7, 2.7), R, rand(6.8, 8.9));
    }
    const time = 1.24;
    ballisticVelocity(fromPos, targetPos, time, GRAVITY, ball.vel);
    ball.pos.copy(fromPos);
    ball.active = true;
    ball.bounces = 0;
    ball.lastHitter = G.server;
    ball.superShot = false;
    G.phase = 'rally';
    G.rally = 0;
    stage.trail.setActive(true);
    stage.trail.push(ball.pos);
    effects.burst(ball.pos, {
      count: 14, color: G.server === 'player' ? CYAN : MAGENTA,
      speed: 3.2, speedVar: 1.6, life: 0.4, size: 8, gravity: -2,
    });
    audio.serve();
    ui.feed(`${G.server === 'player' ? 'YOU' : 'VEXA'} SERVE`, G.server === 'player' ? 'gold' : 'pink');
  }

  // ---------------------------------------------------------------- update
  function update(dt) {
    if (G.phase === 'paused') return;
    G.elapsed += dt;
    tick(dt);
    if (G.phase === 'menu') {
      updateMenu(dt);
    } else {
      updateGame(dt);
    }
    updateCamera(dt);
    stage.bloom.strength = damp(stage.bloom.strength, G.warpTime > 0 ? 1.32 : bloomBase, 5, dt);
  }

  function tick(dt) {
    G.dashCd = Math.max(0, G.dashCd - dt);
    G.warpCd = Math.max(0, G.warpCd - dt);
    G.swingCd = Math.max(0, G.swingCd - dt);
    G.playerHitLock = Math.max(0, G.playerHitLock - dt);
    G.shake = Math.max(0, G.shake - dt * 2.7);
    G.fovPunch = damp(G.fovPunch, 0, 6, dt);
    if (G.aiSurgeVisual > 0) {
      G.aiSurgeVisual -= dt;
      if (G.aiSurgeVisual <= 0) ai.setSuper(false);
    }
    if (G.aiSurgeCd > 0) G.aiSurgeCd -= dt;
    if (G.warpTime > 0) {
      G.warpTime -= dt;
      if (G.warpTime <= 0) {
        G.warpTime = 0;
        stage.world.setWarp(false);
        audio.setWarp(false);
        ui.tint(false);
      }
    }
  }

  function updateMenu(dt) {
    move.x = move.tx = 0;
    move.z = move.tz = COURT.playerZ;
    player.root.position.set(0, 0, COURT.playerZ);
    player.animate(dt, G.elapsed, { speed: 0, vx: 0 });
    aiX = Math.sin(G.elapsed * 0.42) * 1.6;
    ai.root.position.set(aiX, 0, COURT.aiZ);
    ai.animate(dt, G.elapsed, { speed: 0.12, vx: Math.cos(G.elapsed * 0.42) * 0.2 });
    ball.pos.set(
      Math.sin(G.elapsed * 0.62) * 3.2,
      1.38 + Math.sin(G.elapsed * 1.15) * 0.42,
      0.6 + Math.cos(G.elapsed * 0.4) * 1.5
    );
    stage.syncBall(ball.pos, G.elapsed);
    stage.ballGroup.visible = true;
    stage.floorGlow.visible = true;
    stage.setBallTint(G.elapsed % 12 < 6 ? CYAN : MAGENTA, false);
    stage.trail.setActive(false);
    aimMarker.setVisible(false);
    landingMarker.setVisible(false);
    aiLandingMarker.setVisible(false);
    ball.active = false;
  }

  function updateGame(dt) {
    updatePlayer(dt);
    const aiDt = G.warpTime > 0 ? dt * 0.34 : dt;
    updateAI(aiDt);

    player.root.updateMatrixWorld(true);
    ai.root.updateMatrixWorld(true);

    if (G.phase === 'rally') {
      checkPlayerContact();
      checkAIContact();
    }

    if (G.phase === 'serve') {
      G.serveTimer -= dt;
      setServeBallPosition();
      if (G.serveTimer <= 0) launchServe();
    } else if (G.phase === 'rally') {
      stepBall(dt * (G.warpTime > 0 ? 0.34 : 1));
      stage.syncBall(ball.pos, G.elapsed);
      if (ball.active) trail.push(ball.pos);
      if (ball.active) checkPlayerContact();
    } else if (G.phase === 'point') {
      G.pointTimer -= dt;
      if (G.pointTimer <= 0) {
        if (G.playerScore >= 7 || G.aiScore >= 7) endMatch();
        else {
          G.server = G.server === 'player' ? 'ai' : 'player';
          beginServe(true);
        }
      }
    } else if (G.phase === 'over') {
      player.animate(dt, G.elapsed, { speed: 0, vx: 0 });
      ai.animate(dt, G.elapsed, { speed: 0, vx: 0 });
    }

    updateMarkers(dt);
  }

  function updatePlayer(dt) {
    const keys = input.keys;
    let h = 0;
    let v = 0;
    if (keys.has('KeyA') || keys.has('ArrowLeft')) h -= 1;
    if (keys.has('KeyD') || keys.has('ArrowRight')) h += 1;
    if (keys.has('KeyW') || keys.has('ArrowUp')) v -= 1;
    if (keys.has('KeyS') || keys.has('ArrowDown')) v += 1;
    if (h || v) {
      move.tx = clamp(move.tx + h * 7.2 * dt, -4.78, 4.78);
      move.tz = clamp(move.tz + v * 5.0 * dt, 4.9, 9.45);
    }
    if (input.touch.active) {
      move.tx = clamp(move.tx + input.touch.x * 7.4 * dt, -4.78, 4.78);
      move.tz = clamp(move.tz + input.touch.y * 5.2 * dt, 4.9, 9.45);
    }
    move.tx = clamp(move.tx, -4.78, 4.78);
    move.tz = clamp(move.tz, 4.9, 9.45);
    const px = move.x;
    const pz = move.z;
    move.x = damp(move.x, move.tx, 13, dt);
    move.z = damp(move.z, move.tz, 10, dt);
    move.vx = (move.x - px) / Math.max(dt, 0.001);
    move.vz = (move.z - pz) / Math.max(dt, 0.001);
    player.root.position.set(move.x, 0, move.z);
    const speed = clamp(Math.hypot(move.vx, move.vz) / 7.4, 0, 1);
    player.setSuper(G.superArmed);
    player.animate(dt, G.elapsed, { speed, vx: move.vx });
  }

  function updateAI(dt) {
    aiSwingCd = Math.max(0, aiSwingCd - dt);
    const prevX = aiX;
    if (G.aiStun > 0) {
      G.aiStun -= dt;
      aiX = clamp(aiX + G.aiKnock * dt * 4.2, -5.0, 5.0);
      ai.root.position.set(aiX, 0, COURT.aiZ);
      ai.animate(dt, G.elapsed, { speed: 0.35, vx: G.aiKnock });
      return;
    }

    let target = 0;
    const incoming = ball.active && ball.vel.z < -0.2;
    if (incoming) {
      const t = (COURT.aiZ - 0.1 - ball.pos.z) / ball.vel.z;
      target = t > -0.3 && t < 3.2 ? ball.pos.x + ball.vel.x * Math.max(0, t) : ball.pos.x;
      target += aiBias + Math.sin(G.elapsed * 2.4) * 0.1;
    } else {
      target = clamp(-move.x * 0.22 + Math.sin(G.elapsed * 0.75) * 0.7, -2.2, 2.2);
    }
    const speed = 4.25 + Math.min(2.5, G.rally * 0.2 + G.playerScore * 0.12);
    aiX = approach(aiX, clamp(target, -4.75, 4.75), speed * dt);
    ai.root.position.set(aiX, 0, COURT.aiZ);
    const vx = (aiX - prevX) / Math.max(dt, 0.001);
    const speedNorm = clamp(Math.abs(vx) / 7, 0, 1);
    ai.animate(dt, G.elapsed, { speed: speedNorm, vx });
    ai.root.updateMatrixWorld(true);

    if (!ball.active || G.phase !== 'rally' || ball.vel.z > -0.2) return;
    if (ball.pos.z > -4.1 || ball.pos.z < -10.6) return;
    if (ball.pos.y > 3.1) return;
    const hoop = ai.getHoopWorld(tmpV);
    if (hoop.distanceTo(ball.pos) < 2.55 && aiSwingCd <= 0) {
      ai.triggerSwing();
      aiSwingCd = 0.42;
      audio.swing();
    }
  }

  // ---------------------------------------------------------------- ball
  function stepBall(dt) {
    if (!ball.active) return;
    const speed = ball.vel.length();
    const steps = clamp(Math.ceil((speed * dt) / 0.18), 1, 10);
    const h = dt / steps;
    for (let i = 0; i < steps; i++) {
      if (!ball.active) return;
      prevPos.copy(ball.pos);
      ball.vel.y += GRAVITY * h;
      ball.pos.addScaledVector(ball.vel, h);

      if (
        (prevPos.z > 0 && ball.pos.z <= 0) ||
        (prevPos.z < 0 && ball.pos.z >= 0)
      ) {
        const yAtNet = prevPos.y + (ball.pos.y - prevPos.y) * (Math.abs(prevPos.z) / Math.max(0.0001, Math.abs(ball.pos.z - prevPos.z)));
        if (Math.abs(ball.pos.x) < COURT.halfW + 0.3 && yAtNet < COURT.netH + 0.03 && yAtNet > 0) {
          netHit();
          return;
        }
      }

      if (ball.pos.y <= R && ball.vel.y < 0) {
        floorBounce();
        if (!ball.active) return;
      }

      if (Math.abs(ball.pos.x) > 20 || Math.abs(ball.pos.z) > 24) {
        ball.active = false;
        awardPoint(opponent(ball.lastHitter), 'OUT', ball.pos);
        return;
      }
    }
  }

  function floorBounce() {
    ball.pos.y = R;
    ball.vel.y = -ball.vel.y * 0.64;
    ball.vel.x *= 0.95;
    ball.vel.z *= 0.95;
    const out = Math.abs(ball.pos.x) > COURT.halfW + 0.06 || Math.abs(ball.pos.z) > COURT.halfL + 0.06;
    const side = ball.pos.z > 0 ? 'player' : 'ai';
    const color = ball.lastHitter === 'player' ? CYAN : MAGENTA;
    effects.burst(ball.pos, {
      count: 12, color, speed: 2.4, speedVar: 1.4, life: 0.32, size: 7,
      gravity: -5, upBias: 0.5, drag: 3,
    });
    effects.wave(ball.pos, { color, maxScale: 1.5, duration: 0.28, flat: true, opacity: 0.5 });
    audio.bounce();
    if (G.phase !== 'rally') return;

    if (out) {
      awardPoint(opponent(ball.lastHitter), 'OUT', ball.pos);
      return;
    }
    if (side === ball.lastHitter) {
      awardPoint(opponent(ball.lastHitter), 'FAULT', ball.pos);
      return;
    }
    ball.bounces++;
    if (ball.bounces >= 2) {
      awardPoint(ball.lastHitter, 'DOUBLE BOUNCE', ball.pos);
      return;
    }
    if (side === 'player') {
      ui.feed('RETURN IT!', 'gold');
      G.shake = Math.max(G.shake, 0.08);
    }
  }

  function netHit() {
    stage.world.netRipple(1.2);
    effects.burst(ball.pos, {
      count: 26, color: 0xffffff, speed: 4.5, speedVar: 2.2, life: 0.45, size: 10, gravity: -4,
    });
    effects.wave(ball.pos, { color: CYAN, maxScale: 2.0, duration: 0.35, opacity: 0.8 });
    audio.net();
    G.shake = Math.max(G.shake, 0.28);
    awardPoint(opponent(ball.lastHitter), 'NET', ball.pos);
  }

  function awardPoint(winner, reason, position) {
    if (G.phase !== 'rally') return;
    const rally = G.rally;
    G.phase = 'point';
    G.pointTimer = 1.85;
    if (winner === 'player') {
      G.playerScore++;
      G.charge = clamp(G.charge + 8, 0, 100);
    } else {
      G.aiScore++;
    }
    G.bestRally = Math.max(G.bestRally, rally);
    const color = winner === 'player' ? LIME : MAGENTA;
    effects.burst(position, {
      count: 42, color, speed: 7.5, speedVar: 4.5, life: 0.8, size: 13,
      gravity: -4, drag: 1.2, upBias: 0.25,
    });
    effects.wave(position, { color, maxScale: 5.4, duration: 0.7, opacity: 0.9 });
    effects.wave(position, { color: 0xffffff, maxScale: 2.4, duration: 0.42, opacity: 0.65 });
    G.shake = Math.max(G.shake, 0.5);
    ball.active = false;
    stage.ballGroup.visible = false;
    stage.floorGlow.visible = false;
    stage.trail.setActive(false);
    aimMarker.setVisible(false);
    landingMarker.setVisible(false);
    aiLandingMarker.setVisible(false);

    ui.banner(
      winner === 'player' ? 'POINT' : 'VEXA SCORES',
      `${reason}  ·  ${G.playerScore} — ${G.aiScore}`,
      winner === 'player' ? 'lime' : 'pink',
      1.5
    );
    ui.feed(`${winner === 'player' ? 'YOU' : 'VEXA'} TAKE THE POINT — ${reason}`, winner === 'player' ? 'gold' : 'pink');
    if (rally > 0) ui.feed(`RALLY x${rally}`, winner === 'player' ? 'gold' : '');
    audio.point(winner === 'player');
    audio.crowd(0.07);
  }

  function endMatch() {
    G.phase = 'over';
    G.superArmed = false;
    player.setSuper(false);
    ai.setSuper(false);
    ball.active = false;
    stage.ballGroup.visible = false;
    stage.floorGlow.visible = false;
    stage.trail.setActive(false);
    aimMarker.setVisible(false);
    landingMarker.setVisible(false);
    aiLandingMarker.setVisible(false);
    ui.clearBanner();
    const win = G.playerScore > G.aiScore;
    ui.showResult({
      win,
      playerScore: G.playerScore,
      aiScore: G.aiScore,
      bestRally: G.bestRally,
      perfects: G.perfects,
      smashes: G.smashes,
    });
    audio.setPaused(true);
    if (win) audio.crowd(0.09);
  }

