  // ---------------------------------------------------------------- contacts
  function checkPlayerContact() {
    if (G.phase !== 'rally' || !ball.active || G.playerHitLock > 0) return;
    if (player.state.swingTime <= 0) return;
    if (ball.pos.z < 0.3) return;
    const hoop = player.getHoopWorld(tmpV);
