    G.shake = Math.max(G.shake, surge ? 0.6 : 0.18);
  }

  function launchReturn(owner, target, quality, superShot, forcedTime) {
    fromPos.copy(ball.pos);
    fromPos.y = Math.max(fromPos.y, 0.34);
    let time = forcedTime;
    if (!time) {
