252:       fromPos.copy(ball.pos);
253:       targetPos.set(rand(-2.7, 2.7), R, rand(6.8, 8.9));
254:     }
255:     const time = 1.24;
256:     ballisticVelocity(fromPos, targetPos, time, GRAVITY, ball.vel);
257:     ball.pos.copy(fromPos);
