273: 
274:   // ---------------------------------------------------------------- update
275:   function update(dt) {
276:     if (G.phase === 'paused') return;
277:     G.elapsed += dt;
278:     tick(dt);
279:     if (G.phase === 'menu') {
280:       updateMenu(dt);
281:     } else {
282:       updateGame(dt);
283:     }
284:     updateCamera(dt);
285:     stage.bloom.strength = damp(stage.bloom.strength, G.warpTime > 0 ? 1.32 : bloomBase, 5, dt);
286:   }
287: 
288:   function tick(dt) {
289:     G.dashCd = Math.max(0, G.dashCd - dt);
290:     G.warpCd = Math.max(0, G.warpCd - dt);
291:     G.swingCd = Math.max(0, G.swingCd - dt);
292:     G.playerHitLock = Math.max(0, G.playerHitLock - dt);
293:     aiHitLock = Math.max(0, aiHitLock - dt);
294:     G.shake = Math.max(0, G.shake - dt * 2.7);
295:     G.fovPunch = damp(G.fovPunch, 0, 6, dt);
296:     if (G.aiSurgeVisual > 0) {
297:       G.aiSurgeVisual -= dt;
298:       if (G.aiSurgeVisual <= 0) ai.setSuper(false);
299:     }
300:     if (G.aiSurgeCd > 0) G.aiSurgeCd -= dt;
301:     if (G.warpTime > 0) {
302:       G.warpTime -= dt;
303:       if (G.warpTime <= 0) {
304:         G.warpTime = 0;
305:         stage.world.setWarp(false);
306:         audio.setWarp(false);
307:         ui.tint(false);
308:       }
309:     }
310:   }
311: 
312:   function updateMenu(dt) {
313:     move.x = move.tx = 0;
314:     move.z = move.tz = COURT.playerZ;
315:     player.root.position.set(0, 0, COURT.playerZ);
316:     player.animate(dt, G.elapsed, { speed: 0, vx: 0 });
317:     aiX = Math.sin(G.elapsed * 0.42) * 1.6;
318:     ai.root.position.set(aiX, 0, COURT.aiZ);
319:     ai.animate(dt, G.elapsed, { speed: 0.12, vx: Math.cos(G.elapsed * 0.42) * 0.2 });
320:     ball.pos.set(
321:       Math.sin(G.elapsed * 0.62) * 3.2,
322:       1.38 + Math.sin(G.elapsed * 1.15) * 0.42,
323:       0.6 + Math.cos(G.elapsed * 0.4) * 1.5
324:     );
325:     stage.syncBall(ball.pos, G.elapsed);
326:     stage.ballGroup.visible = true;
327:     stage.floorGlow.visible = true;
328:     stage.setBallTint(G.elapsed % 12 < 6 ? CYAN : MAGENTA, false);
329:     stage.trail.setActive(false);
330:     aimMarker.setVisible(false);
331:     landingMarker.setVisible(false);
332:     aiLandingMarker.setVisible(false);
333:     ball.active = false;
334:   }
335: 
336:   function updateGame(dt) {
337:     updatePlayer(dt);
338:     const aiDt = G.warpTime > 0 ? dt * 0.34 : dt;
339:     updateAI(aiDt);
340: 
341:     player.root.updateMatrixWorld(true);
342:     ai.root.updateMatrixWorld(true);
343: 
344:     if (G.phase === 'rally') {
345:       checkPlayerContact();
346:       checkAIContact();
347:     }
348: 
349:     if (G.phase === 'serve') {
350:       G.serveTimer -= dt;
351:       setServeBallPosition();
352:       if (G.serveTimer <= 0) launchServe();
353:     } else if (G.phase === 'rally') {
354:       stepBall(dt * (G.warpTime > 0 ? 0.34 : 1));
355:       stage.syncBall(ball.pos, G.elapsed);
356:       if (ball.active) trail.push(ball.pos);
357:       if (ball.active) checkPlayerContact();
358:     } else if (G.phase === 'point') {
359:       G.pointTimer -= dt;
360:       if (G.pointTimer <= 0) {
361:         if (G.playerScore >= 7 || G.aiScore >= 7) endMatch();
362:         else {
363:           G.server = G.server === 'player' ? 'ai' : 'player';
364:           beginServe(true);
365:         }
366:       }
367:     } else if (G.phase === 'over') {
368:       player.animate(dt, G.elapsed, { speed: 0, vx: 0 });
369:       ai.animate(dt, G.elapsed, { speed: 0, vx: 0 });
370:     }
371: 
372:     updateMarkers(dt);
373:   }
374: 
375:   function updatePlayer(dt) {
376:     const keys = input.keys;
377:     let h = 0;
378:     let v = 0;
379:     if (keys.has('KeyA') || keys.has('ArrowLeft')) h -= 1;
380:     if (keys.has('KeyD') || keys.has('ArrowRight')) h += 1;
381:     if (keys.has('KeyW') || keys.has('ArrowUp')) v -= 1;
382:     if (keys.has('KeyS') || keys.has('ArrowDown')) v += 1;
383:     if (h || v) {
384:       move.tx = clamp(move.tx + h * 7.2 * dt, -4.78, 4.78);
385:       move.tz = clamp(move.tz + v * 5.0 * dt, 4.9, 9.45);
386:     }
387:     if (input.touch.active) {
388:       move.tx = clamp(move.tx + input.touch.x * 7.4 * dt, -4.78, 4.78);
389:       move.tz = clamp(move.tz + input.touch.y * 5.2 * dt, 4.9, 9.45);
390:     }
391:     move.tx = clamp(move.tx, -4.78, 4.78);
392:     move.tz = clamp(move.tz, 4.9, 9.45);
393:     const px = move.x;
394:     const pz = move.z;
395:     move.x = damp(move.x, move.tx, 13, dt);
396:     move.z = damp(move.z, move.tz, 10, dt);
397:     move.vx = (move.x - px) / Math.max(dt, 0.001);
398:     move.vz = (move.z - pz) / Math.max(dt, 0.001);
399:     player.root.position.set(move.x, 0, move.z);
400:     const speed = clamp(Math.hypot(move.vx, move.vz) / 7.4, 0, 1);
401:     player.setSuper(G.superArmed);
402:     player.animate(dt, G.elapsed, { speed, vx: move.vx });
403:   }
404: 
405:   function updateAI(dt) {
406:     aiSwingCd = Math.max(0, aiSwingCd - dt);
407:     const prevX = aiX;
408:     if (G.aiStun > 0) {
409:       G.aiStun -= dt;
410:       aiX = clamp(aiX + G.aiKnock * dt * 4.2, -5.0, 5.0);
411:       ai.root.position.set(aiX, 0, COURT.aiZ);
412:       ai.animate(dt, G.elapsed, { speed: 0.35, vx: G.aiKnock });
413:       return;
414:     }
415: 
416:     let target = 0;
417:     const incoming = ball.active && ball.vel.z < -0.2;
418:     if (incoming) {
419:       const t = (COURT.aiZ - 0.1 - ball.pos.z) / ball.vel.z;
420:       target = t > -0.3 && t < 3.2 ? ball.pos.x + ball.vel.x * Math.max(0, t) : ball.pos.x;
421:       target += aiBias + Math.sin(G.elapsed * 2.4) * 0.1;
422:     } else {
423:       target = clamp(-move.x * 0.22 + Math.sin(G.elapsed * 0.75) * 0.7, -2.2, 2.2);
424:     }
425:     const speed = 4.25 + Math.min(2.5, G.rally * 0.2 + G.playerScore * 0.12);
426:     aiX = approach(aiX, clamp(target, -4.75, 4.75), speed * dt);
427:     ai.root.position.set(aiX, 0, COURT.aiZ);
428:     const vx = (aiX - prevX) / Math.max(dt, 0.001);
429:     const speedNorm = clamp(Math.abs(vx) / 7, 0, 1);
430:     ai.animate(dt, G.elapsed, { speed: speedNorm, vx });
431:     ai.root.updateMatrixWorld(true);
432: 
433:     if (!ball.active || G.phase !== 'rally' || ball.vel.z > -0.2) return;
434:     if (ball.pos.z > -4.1 || ball.pos.z < -10.6) return;
435:     if (ball.pos.y > 3.1) return;
436:     const hoop = ai.getHoopWorld(tmpV);
437:     if (hoop.distanceTo(ball.pos) < 2.55 && aiSwingCd <= 0) {
438:       ai.triggerSwing();
439:       aiSwingCd = 0.42;
440:       audio.swing();
441:     }
442:   }
443: 
444:   // ---------------------------------------------------------------- ball
445:   function stepBall(dt) {
446:     if (!ball.active) return;
447:     const speed = ball.vel.length();
448:     const steps = clamp(Math.ceil((speed * dt) / 0.18), 1, 10);
449:     const h = dt / steps;
450:     for (let i = 0; i < steps; i++) {
451:       if (!ball.active) return;
452:       prevPos.copy(ball.pos);
453:       ball.vel.y += GRAVITY * h;
454:       ball.pos.addScaledVector(ball.vel, h);
455: 
456:       if (
457:         (prevPos.z > 0 && ball.pos.z <= 0) ||
458:         (prevPos.z < 0 && ball.pos.z >= 0)
459:       ) {
460:         const yAtNet = prevPos.y + (ball.pos.y - prevPos.y) * (Math.abs(prevPos.z) / Math.max(0.0001, Math.abs(ball.pos.z - prevPos.z)));
461:         if (Math.abs(ball.pos.x) < COURT.halfW + 0.3 && yAtNet < COURT.netH + 0.03 && yAtNet > 0) {
462:           netHit();
463:           return;
464:         }
465:       }
466: 
467:       if (ball.pos.y <= R && ball.vel.y < 0) {
468:         floorBounce();
469:         if (!ball.active) return;
470:       }
471: 
472:       if (Math.abs(ball.pos.x) > 20 || Math.abs(ball.pos.z) > 24) {
473:         ball.active = false;
474:         awardPoint(opponent(ball.lastHitter), 'OUT', ball.pos);
475:         return;
476:       }
477:     }
478:   }
479: 
480:   function floorBounce() {
481:     ball.pos.y = R;
482:     ball.vel.y = -ball.vel.y * 0.64;
483:     ball.vel.x *= 0.95;
484:     ball.vel.z *= 0.95;
485:     const out = Math.abs(ball.pos.x) > COURT.halfW + 0.06 || Math.abs(ball.pos.z) > COURT.halfL + 0.06;
486:     const side = ball.pos.z > 0 ? 'player' : 'ai';
487:     const color = ball.lastHitter === 'player' ? CYAN : MAGENTA;
488:     effects.burst(ball.pos, {
489:       count: 12, color, speed: 2.4, speedVar: 1.4, life: 0.32, size: 7,
490:       gravity: -5, upBias: 0.5, drag: 3,
491:     });
492:     effects.wave(ball.pos, { color, maxScale: 1.5, duration: 0.28, flat: true, opacity: 0.5 });
493:     audio.bounce();
494:     if (G.phase !== 'rally') return;
495: 
496:     if (out) {
497:       awardPoint(opponent(ball.lastHitter), 'OUT', ball.pos);
498:       return;
499:     }
500:     if (side === ball.lastHitter) {
501:       awardPoint(opponent(ball.lastHitter), 'FAULT', ball.pos);
502:       return;
503:     }
504:     ball.bounces++;
505:     if (ball.bounces >= 2) {
506:       awardPoint(ball.lastHitter, 'DOUBLE BOUNCE', ball.pos);
507:       return;
508:     }
509:     if (side === 'player') {
510:       ui.feed('RETURN IT!', 'gold');
511:       G.shake = Math.max(G.shake, 0.08);
512:     }
513:   }
514: 
515:   function netHit() {
516:     stage.world.netRipple(1.2);
517:     effects.burst(ball.pos, {
518:       count: 26, color: 0xffffff, speed: 4.5, speedVar: 2.2, life: 0.45, size: 10, gravity: -4,
519:     });
520:     effects.wave(ball.pos, { color: CYAN, maxScale: 2.0, duration: 0.35, opacity: 0.8 });
521:     audio.net();
522:     G.shake = Math.max(G.shake, 0.28);
523:     awardPoint(opponent(ball.lastHitter), 'NET', ball.pos);
524:   }
525: 
526:   function awardPoint(winner, reason, position) {
527:     if (G.phase !== 'rally') return;
528:     const rally = G.rally;
529:     G.phase = 'point';
530:     G.pointTimer = 1.85;
531:     if (winner === 'player') {
532:       G.playerScore++;
533:       G.charge = clamp(G.charge + 8, 0, 100);
534:     } else {
535:       G.aiScore++;
536:     }
537:     G.bestRally = Math.max(G.bestRally, rally);
538:     const color = winner === 'player' ? LIME : MAGENTA;
539:     effects.burst(position, {
540:       count: 42, color, speed: 7.5, speedVar: 4.5, life: 0.8, size: 13,
541:       gravity: -4, drag: 1.2, upBias: 0.25,
542:     });
543:     effects.wave(position, { color, maxScale: 5.4, duration: 0.7, opacity: 0.9 });
544:     effects.wave(position, { color: 0xffffff, maxScale: 2.4, duration: 0.42, opacity: 0.65 });
545:     G.shake = Math.max(G.shake, 0.5);
546:     ball.active = false;
547:     stage.ballGroup.visible = false;
548:     stage.floorGlow.visible = false;
549:     stage.trail.setActive(false);
550:     aimMarker.setVisible(false);
551:     landingMarker.setVisible(false);
552:     aiLandingMarker.setVisible(false);
553: 
554:     ui.banner(
555:       winner === 'player' ? 'POINT' : 'VEXA SCORES',
556:       `${reason}  ·  ${G.playerScore} — ${G.aiScore}`,
557:       winner === 'player' ? 'lime' : 'pink',
558:       1.5
559:     );
560:     ui.feed(`${winner === 'player' ? 'YOU' : 'VEXA'} TAKE THE POINT — ${reason}`, winner === 'player' ? 'gold' : 'pink');
561:     if (rally > 0) ui.feed(`RALLY x${rally}`, winner === 'player' ? 'gold' : '');
562:     audio.point(winner === 'player');
563:     audio.crowd(0.07);
564:   }
565: 
566:   function endMatch() {
567:     G.phase = 'over';
568:     G.superArmed = false;
569:     player.setSuper(false);
570:     ai.setSuper(false);
571:     ball.active = false;
572:     stage.ballGroup.visible = false;
573:     stage.floorGlow.visible = false;
574:     stage.trail.setActive(false);
575:     aimMarker.setVisible(false);
576:     landingMarker.setVisible(false);
577:     aiLandingMarker.setVisible(false);
578:     ui.clearBanner();
579:     const win = G.playerScore > G.aiScore;
580:     ui.showResult({
581:       win,
582:       playerScore: G.playerScore,
583:       aiScore: G.aiScore,
584:       bestRally: G.bestRally,
585:       perfects: G.perfects,
586:       smashes: G.smashes,
587:     });
588:     audio.setPaused(true);
589:     if (win) audio.crowd(0.09);
590:   }
591: 
592:   // ---------------------------------------------------------------- contacts
593:   function checkPlayerContact() {
594:     if (G.phase !== 'rally' || !ball.active || G.playerHitLock > 0) return;
595:     if (player.state.swingTime <= 0) return;
596:     if (ball.pos.z < 0.3) return;
597:     const hoop = player.getHoopWorld(tmpV);
598:     const d = hoop.distanceTo(ball.pos);
599:     if (d < 1.95) resolvePlayerReturn(d);
600:   }
601: 
602:   function checkAIContact() {
603:     if (G.phase !== 'rally' || !ball.active || aiHitLock > 0) return;
604:     if (ai.state.swingTime <= 0) return;
605:     if (ball.pos.z > -0.3) return;
606:     const hoop = ai.getHoopWorld(tmpV);
607:     const d = hoop.distanceTo(ball.pos);
608:     if (d < 1.95) resolveAIShot(d);
609:   }
610: 
611:   function resolvePlayerReturn(d) {
612:     if (G.playerHitLock > 0 || G.phase !== 'rally') return;
613:     G.playerHitLock = 0.34;
614:     const quality = d < 0.74 ? 'perfect' : d < 1.32 ? 'good' : 'edge';
615:     const superShot = G.superArmed;
616:     const target = playerAimTarget();
617:     if (quality === 'edge' && !superShot) target.x = clamp(target.x + rand(-1.1, 1.1), -4.5, 4.5);
618:     if (superShot) {
619:       G.superArmed = false;
620:       G.charge = 0;
621:       G.smashes++;
622:       player.setSuper(false);
623:       target.x = clamp(target.x, -3.9, 3.9);
624:       target.z = -8.85;
625:       G.aiStun = 1.05;
626:       G.aiKnock = (Math.random() < 0.5 ? -1 : 1) * 1.35;
627:       ui.flash('fire');
628:       ui.feed('SUPER SMASH — UNRETURNABLE', 'gold');
629:       G.shake = Math.max(G.shake, 1.0);
630:       G.fovPunch = 7;
631:       audio.smash();
632:     } else {
633:       const gain = quality === 'perfect' ? 14 : quality === 'good' ? 8 : 5;
634:       G.charge = clamp(G.charge + gain, 0, 100);
635:       if (quality === 'perfect') {
636:         G.perfects++;
637:         ui.feed('PERFECT RETURN +14', 'gold');
638:         G.shake = Math.max(G.shake, 0.28);
639:       } else if (quality === 'edge') {
640:         ui.feed('EDGE RETURN', '');
641:       }
642:       audio.hit(quality, false);
643:     }
644: 
645:     G.rally++;
646:     G.bestRally = Math.max(G.bestRally, G.rally);
647:     launchReturn('player', target, quality, superShot);
648:     strikeEffects('player', quality, superShot);
649:     if (!superShot) {
650:       aiBias = rand(-0.32, 0.32) + (quality === 'perfect' ? rand(-0.8, 0.8) : 0);
651:     }
652:   }
653: 
654:   function resolveAIShot(d) {
