3: import { createGame } from './game.js';
4: 
5: const isTouch =
6:   window.matchMedia?.('(pointer: coarse)').matches ||
7:   (navigator.maxTouchPoints || 0) > 0 ||
8:   window.innerWidth <= 820;
9: 
10: document.body.classList.toggle('touch', isTouch);
11: 
12: let stage = null;
13: let game = null;
14: 
15: const ui = new UI({
16:   onPlay: () => game?.startMatch(),
17:   onMenu: () => game?.goMenu(),
18:   onPause: () => game?.togglePause(),
19:   onRestart: () => game?.startMatch(),
20:   onMute: () => game?.toggleMute(),
21:   onPower: (power) => game?.usePower(power),
22:   onSwing: () => game?.swing(),
23: });
24: ui.setTouch(isTouch);
25: 
26: try {
27:   stage = createStage(document.getElementById('scene'), { isTouch });
28:   game = createGame({ stage, ui, isTouch });
29:   game.goMenu();
30: } catch (error) {
31:   console.error(error);
32:   ui.error('WEBGL UNAVAILABLE — TRY A NEWER BROWSER');
33: }
34: 
35: let last = performance.now();
36: let visualTime = 0;
37: 
38: function frame(now) {
39:   requestAnimationFrame(frame);
40:   const raw = Math.min(0.05, Math.max(0, (now - last) / 1000));
41:   last = now;
42: 
43:   if (stage && game) {
44:     const dt = game.state.phase === 'paused' ? 0 : raw;
45:     game.update(dt);
46:     if (dt > 0) visualTime += dt;
47:     stage.tick(dt, visualTime);
48:     ui.update(raw, game.state);
49:     stage.render();
50:   }
51: }
52: requestAnimationFrame(frame);
53: 
54: const fontsReady = document.fonts?.ready ?? Promise.resolve();
55: Promise.race([
56:   fontsReady,
57:   new Promise((resolve) => setTimeout(resolve, 1400)),
58: ]).then(() => {
59:   setTimeout(() => ui.loaderDone(), 220);
60: });
61: 
62: document.addEventListener('visibilitychange', () => {
63:   if (!game) return;
64:   const phase = game.state.phase;
65:   if (document.hidden && (phase === 'serve' || phase === 'rally' || phase === 'point')) {
66:     game.togglePause();
67:   }
68: });
